window.SDT_NOTES=window.SDT_NOTES||{};window.SDT_NOTES["b"]={"week":"b","title":"기초 다지기. 건물을 보고 말하는 법","units":[{"id":"wb-1","title":"파사드, 건물의 얼굴","goal":"사진 한 장을 보고 **파사드(Facade)**를 네 걸음으로 읽어 말할 수 있어요.","terms":[{"ko":"파사드","en":"Facade","say":"건물에서 길을 향한 주된 겉면, 곧 건물의 얼굴","more":"양식의 특징이 가장 많이 드러나는 면이에요. 이 과목의 사진 문제는 거의 파사드를 보여 줘요."},{"ko":"입면","en":"Elevation","say":"건물 한 면을 정면으로 마주 보고 그린 그림","more":"개구부와 장식이 어떻게 줄 서 있는지가 보여요. 사진에 찍힌 얼굴이 대개 입면이에요."},{"ko":"개구부","en":"Opening","say":"벽에 뚫어 놓은 창과 문 자리","more":"크기와 모양과 배열이 양식을 가르는 첫 단서예요. 격자인지 아치인지 띠창인지를 봐요."},{"ko":"기단","en":"Base","say":"건물 맨 아래에서 몸통을 받쳐 주는 부분","more":"에펠탑은 기단, 몸통, 탑으로 구성되고, 설리번의 3단구성법에서도 저층부를 base 라고 불러요."},{"ko":"코니스","en":"Cornice","say":"건물 꼭대기에서 밖으로 내밀어 마감한 띠","more":"설리번의 웨인라이트 빌딩에는 우아한 코니스가 있고, 시카고 학파 고층 건물은 코니스를 기둥의 주두처럼 써요."},{"ko":"비례","en":"Proportion","say":"부분과 부분, 부분과 전체의 크기 관계","more":"절충주의는 전통적인 비례체계를 무시했고, 로스의 무장식은 비례를 더욱 돋보이게 한다고 평가돼요."},{"ko":"양식","en":"Style","say":"한 시기의 건물들이 함께 지키는 형태의 규칙과 그 이름","more":"시험은 사진을 주고 양식 이름을 묻고, 논술은 그 양식을 아는 대로 모두 쓰라고 해요."}],"slides":[{"kind":"title","big":"파사드 읽기","sub":"이 과목 사진은 거의 다 건물의 얼굴 사진이에요"},{"kind":"goal","items":["**파사드(Facade)**가 무엇인지 말하고 사진에서 찾아요.","덩어리, **개구부(Opening)**, 재료, 장식의 네 걸음으로 얼굴을 읽어요.","장식만 보고 **양식(Style)**의 자리를 반쯤 좁혀요."]},{"kind":"points","head":"이 과목을 여는 주문","items":["기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","이 한 줄이 여섯 단원을 꿰어요. 곡선이 직선이 되고 결국 장식이 사라져요.","그 변화가 어디에 나타날까요? 건물의 얼굴, 곧 **파사드(Facade)**에 나타나요."]},{"kind":"points","head":"**파사드(Facade)**가 무엇인가요","items":["건물에서 길을 향한 주된 겉면이에요. 사람이 제일 먼저 마주 보는 면이죠.","그 면을 정면으로 마주 보고 그린 그림이 **입면(Elevation)**이에요.","사진에 찍힌 얼굴이 대개 **입면(Elevation)**이고, 그 얼굴이 바로 **파사드(Facade)**예요.","시험 사진은 거의 **파사드(Facade)**예요. 그래서 얼굴 읽는 법부터 배워요."]},{"kind":"analogy","head":"사람 얼굴 보듯 건물 얼굴 보기","scene":"처음 만난 사람은 얼굴 크기, 눈코입 자리, 피부, 화장 순으로 보게 되죠.","map":[["얼굴 크기와 생김새","덩어리와 **비례(Proportion)**"],["눈과 코와 입의 자리","**개구부(Opening)**"],["피부","겉벽에 쓴 재료"],["화장","장식이 있는지 없는지"]]},{"kind":"figure","head":"**파사드(Facade)**를 읽는 네 걸음","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">파사드에서 읽는 네 가지<\/text><rect x=\"34\" y=\"62\" width=\"182\" height=\"14\" rx=\"2\" class=\"n3 b1\"/><text x=\"125.0\" y=\"73.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">코니스<\/text><rect x=\"40\" y=\"76\" width=\"170\" height=\"132\" rx=\"2\" class=\"n b1\"/><rect x=\"60\" y=\"92\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"110\" y=\"92\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"160\" y=\"92\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"60\" y=\"128\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"110\" y=\"128\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"160\" y=\"128\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"60\" y=\"164\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"110\" y=\"164\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"160\" y=\"164\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"40\" y=\"208\" width=\"170\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><text x=\"125.0\" y=\"228.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">기단<\/text><text x=\"125.0\" y=\"256.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">재료와 장식도 여기서<\/text><rect x=\"250\" y=\"46\" width=\"214\" height=\"44\" rx=\"2\" class=\"box b1\"/><text x=\"357.0\" y=\"64.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">1 덩어리와 층수<\/text><text x=\"357.0\" y=\"83.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">덩어리가 몇 개인가<\/text><rect x=\"250\" y=\"98\" width=\"214\" height=\"44\" rx=\"2\" class=\"box b2\"/><text x=\"357.0\" y=\"116.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">2 개구부<\/text><text x=\"357.0\" y=\"135.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">창과 문의 크기와 배열<\/text><rect x=\"250\" y=\"150\" width=\"214\" height=\"44\" rx=\"2\" class=\"box b3\"/><text x=\"357.0\" y=\"168.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">3 재료<\/text><text x=\"357.0\" y=\"187.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">돌 벽돌 회반죽 타일 철 유리<\/text><rect x=\"250\" y=\"202\" width=\"214\" height=\"44\" rx=\"2\" class=\"box2 b4\"/><text x=\"357.0\" y=\"220.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b4\">4 장식<\/text><text x=\"357.0\" y=\"239.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">곡선인가 기하인가 없는가<\/text><\/svg>","caption":"덩어리와 **비례(Proportion)**, **개구부(Opening)**, 재료, 장식 순서로 보면 빠짐없이 읽혀요.","builds":4},{"kind":"points","head":"1걸음 덩어리와 층수","items":["먼저 건물이 몇 덩어리인지, 몇 층인지 세요.","부분과 부분, 부분과 전체의 크기 관계를 **비례(Proportion)**라고 해요.","맨 아래에서 몸통을 받쳐 주는 부분이 **기단(Base)**이에요.","꼭대기에서 밖으로 내밀어 마감한 띠가 **코니스(Cornice)**예요.","**기단(Base)**, 몸통, **코니스(Cornice)**의 세 칸으로 나뉘면 시카고 학파 고층 건물일 때가 많아요."]},{"kind":"points","head":"2걸음 **개구부(Opening)**","items":["**개구부(Opening)**는 벽에 뚫어 놓은 창과 문 자리예요.","작고 띄엄띄엄하면 벽이 무게를 받는 옛 방식일 가능성이 커요.","격자로 꽉 차거나 가로로 긴 띠창이면 뼈대가 무게를 받는 새 방식이에요.","5단원에서 볼 **커튼월(curtain wall)**이 바로 그 새 방식의 결과예요."]},{"kind":"figure","head":"**개구부(Opening)**의 세 가지 얼굴","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">개구부가 시대를 말해요<\/text><rect x=\"14\" y=\"46\" width=\"140\" height=\"160\" rx=\"2\" class=\"n b1\"/><rect x=\"170\" y=\"46\" width=\"140\" height=\"160\" rx=\"2\" class=\"n b2\"/><rect x=\"326\" y=\"46\" width=\"140\" height=\"160\" rx=\"2\" class=\"n2 b3\"/><rect x=\"40\" y=\"70\" width=\"26\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><rect x=\"100\" y=\"70\" width=\"26\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><rect x=\"40\" y=\"130\" width=\"26\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><rect x=\"100\" y=\"130\" width=\"26\" height=\"30\" rx=\"2\" class=\"n3 b1\"/><rect x=\"184\" y=\"70\" width=\"36\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><rect x=\"226\" y=\"70\" width=\"36\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><rect x=\"268\" y=\"70\" width=\"36\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><rect x=\"184\" y=\"110\" width=\"36\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><rect x=\"226\" y=\"110\" width=\"36\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><rect x=\"268\" y=\"110\" width=\"36\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><rect x=\"184\" y=\"150\" width=\"36\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><rect x=\"226\" y=\"150\" width=\"36\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><rect x=\"268\" y=\"150\" width=\"36\" height=\"30\" rx=\"2\" class=\"n3 b2\"/><rect x=\"338\" y=\"80\" width=\"116\" height=\"24\" rx=\"2\" class=\"n3 b3\"/><rect x=\"338\" y=\"124\" width=\"116\" height=\"24\" rx=\"2\" class=\"n3 b3\"/><rect x=\"338\" y=\"168\" width=\"116\" height=\"24\" rx=\"2\" class=\"n3 b3\"/><text x=\"84.0\" y=\"224.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">작고 띄엄띄엄<\/text><text x=\"240.0\" y=\"224.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">격자로 꽉 참<\/text><text x=\"396.0\" y=\"224.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b3\">가로로 긴 띠창<\/text><text x=\"240.0\" y=\"252.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">돌로 쌓으면 작아지고 철과 유리면 넓어져요<\/text><\/svg>","caption":"가운데는 시카고 창이에요. 셋으로 나뉜 격자가 돌출돼 있어요.","builds":4},{"kind":"points","head":"3걸음 재료, 4걸음 장식","items":["재료는 돌, 벽돌, 회반죽, 타일, 철, 유리 가운데 무엇이 보이는지 봐요.","장식은 셋 중 하나예요. 자연에서 딴 곡선, 자로 그은 기하, 아니면 없음.","**로스하우스**는 장식이 없어서 곡물창고라고 놀림을 받았어요.","이 네 걸음이 **양식(Style)**을 좁히는 가장 빠른 길이에요."]},{"kind":"figure","head":"장식이 사라지는 세 얼굴","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"24.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b1\">곡선이 직선이 되고 장식이 사라져요<\/text><rect x=\"14\" y=\"50\" width=\"140\" height=\"150\" rx=\"2\" class=\"n b1\"/><rect x=\"170\" y=\"50\" width=\"140\" height=\"150\" rx=\"2\" class=\"n b2\"/><rect x=\"326\" y=\"50\" width=\"140\" height=\"150\" rx=\"2\" class=\"n2 b3\"/><path d=\"M34 140 Q 54 100 84 125 T 134 110\" fill=\"none\" class=\"e2 b1\"/><path d=\"M34 165 Q 54 125 84 150 T 134 135\" fill=\"none\" class=\"e2 b1\"/><rect x=\"196\" y=\"86\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><rect x=\"246\" y=\"86\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><rect x=\"196\" y=\"136\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><rect x=\"246\" y=\"136\" width=\"38\" height=\"38\" rx=\"2\" class=\"n3 b2\"/><line x1=\"346.0\" y1=\"125.0\" x2=\"446.0\" y2=\"125.0\" class=\"e b3\"/><text x=\"84.0\" y=\"218.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b1\">곡선 장식<\/text><text x=\"240.0\" y=\"218.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b2\">기하로 정리<\/text><text x=\"396.0\" y=\"218.0\" font-size=\"15\" text-anchor=\"middle\" class=\"t b3\">장식 없음<\/text><text x=\"240.0\" y=\"250.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b4\">싫어 -&gt; 새 장식 -&gt; 정리 -&gt; 없애<\/text><\/svg>","caption":"이 세 칸이 이 과목의 뼈대예요. **양식(Style)**은 장식만 봐도 반쯤 좁혀져요.","builds":4},{"kind":"compare","head":"**파사드(Facade)**로 알 수 있는 것과 없는 것","cols":["무엇을 묻나","대답"],"rows":[["겉벽 재료와 장식","보여요"],["**개구부(Opening)**의 크기와 배열","보여요"],["방이 서로 어떻게 이어지나","안 보여요. 평면을 봐야 해요"],["방마다 높이가 다른가","안 보여요. 단면을 봐야 해요"]]},{"kind":"english","head":"논술 답안에 쓸 문장","en":"파사드는 건물에서 길을 향한 주된 겉면으로, 덩어리와 개구부와 재료와 장식의 순서로 읽는다.","ko":"네 걸음을 그대로 한 문장으로 옮긴 거예요.","tip":"덩어리, 개구부, 재료, 장식 순서로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**파사드(Facade)**는 겉면 자체이고 **입면(Elevation)**은 그 면을 그린 그림이에요.","**코니스(Cornice)**는 꼭대기 장식 띠, **기단(Base)**은 맨 아래 받침이에요. 자리를 바꿔 묻는 문제가 나와요.","창이 크다고 무조건 새 건물은 아니에요. 재료와 장식을 함께 봐야 해요."]},{"kind":"check","q":"**개구부(Opening)**가 뜻하는 것으로 알맞은 것은?","choices":["벽에 뚫어 놓은 창과 문 자리","지붕이 벽 밖으로 내민 부분","건물 맨 아래의 받침","꼭대기에서 내민 장식 띠"],"a":0,"why":"지붕이 내민 것은 처마, 맨 아래는 **기단(Base)**, 꼭대기 띠는 **코니스(Cornice)**예요."},{"kind":"check","q":"사진 한 장의 **파사드(Facade)**만 보고는 알 수 없는 것은?","choices":["방들이 서로 어떻게 이어지는지","겉벽에 쓴 재료","장식이 있는지 없는지","창의 크기와 배열"],"a":0,"why":"방의 연결은 평면을 봐야 알아요. 나머지 셋은 얼굴만 봐도 보여요."},{"kind":"points","head":"이게 이 과목 어디에 나오나","items":["U2 p.57, p.60: 설리번의 격자 **파사드(Facade)** 구성과 2층 높이 주철 **파사드(Facade)**.","U3 p.20, p.40: 표면이 구조와 분리된 마욜리카하우스, 녹색 대리석의 로스하우스.","U4 p.15-16: 데사우 바우하우스 교사의 3층 높이 유리 **커튼월(curtain wall)**과 정면 없는 구성.","U6 p.12: 칠레하우스의 벽돌 각기둥을 나열한 듯한 **파사드(Facade)**.","시험 모양: 사진을 주고 이름, 건축가, 연도, **양식(Style)**을 묻는 객관식이 가장 많아요."]},{"kind":"recap","items":["**파사드(Facade)**는 건물에서 길을 향한 주된 겉면이에요.","네 걸음: 덩어리와 층수, **개구부(Opening)**, 재료, 장식.","**기단(Base)**은 맨 아래 받침, **코니스(Cornice)**는 꼭대기 장식 띠예요.","그림으로 그린 얼굴이 **입면(Elevation)**이고, 장식이 **양식(Style)**을 좁혀 줘요.","기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","오늘의 용어: 파사드(Facade), 입면(Elevation), 개구부(Opening), 기단(Base), 코니스(Cornice), 비례(Proportion), 양식(Style)"]}]},{"id":"wb-2","title":"평면과 입면과 단면","goal":"**평면(Plan)**, **입면(Elevation)**, **단면(Section)**이 각각 무엇을 보여 주는지 갈라서 말할 수 있어요.","terms":[{"ko":"평면","en":"Plan","say":"건물을 가로로 잘라 위에서 내려다본 그림","more":"방이 어떻게 놓이고 사람이 어디로 다니는지가 보여요. 사진만으로는 알 수 없는 정보예요."},{"ko":"입면","en":"Elevation","say":"건물 한 면을 정면으로 마주 보고 그린 그림","more":"개구부와 장식이 어떻게 줄 서 있는지가 보여요. 사진에 찍힌 얼굴이 대개 입면이에요."},{"ko":"단면","en":"Section","say":"건물을 세로로 잘라 옆에서 들여다본 그림","more":"층고와 높이 차이, 지붕의 모양이 보여요. 로스의 라움플란처럼 높이로 승부하는 집은 단면을 봐야 해요."},{"ko":"층고","en":"Floor Height","say":"한 층의 바닥에서 위층 바닥까지의 높이","more":"바그너는 각 층의 층고를 동일하게 평준화했고, 로스는 방마다 층고를 다르게 주는 라움플란을 썼어요."},{"ko":"중정","en":"Courtyard","say":"건물이 빙 둘러싼 가운데의 큰 마당"},{"ko":"라움플란","en":"Raumplan","say":"방마다 필요한 높이를 따로 주고 입체적으로 맞물리는 로스의 설계법","more":"'나는 평면, 입면, 단면이 아니라 공간을 설계한다'. 거실을 두 개 층으로 개방. 라움쿤스트와 구분."}],"slides":[{"kind":"title","big":"평면 입면 단면","sub":"어디를 자르느냐에 따라 다른 그림이 나와요"},{"kind":"goal","items":["**평면(Plan)**, **입면(Elevation)**, **단면(Section)**의 뜻을 갈라서 말해요.","그림마다 무엇이 보이고 무엇이 안 보이는지 대요.","**라움플란(Raumplan)**이 왜 **단면(Section)**의 이야기인지 설명해요."]},{"kind":"points","head":"앞 단원에서 이어 붙이기","items":["기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","앞에서 본 **파사드(Facade)**는 겉면이고, 사진에 찍히는 얼굴이었죠.","그런데 **개구부(Opening)**의 크기와 배열만으로는 방의 생김새를 알 수 없었어요.","그래서 건축가는 그림을 세 가지로 나눠 그려요."]},{"kind":"points","head":"세 가지 그림","items":["**평면(Plan)**은 건물을 가로로 잘라 위에서 내려다본 그림이에요.","**입면(Elevation)**은 한 면을 정면으로 마주 보고 그린 그림이에요.","**단면(Section)**은 세로로 잘라 옆에서 들여다본 그림이에요.","가로로 자르면 **평면(Plan)**, 세로로 자르면 **단면(Section)**이라고 외우면 쉬워요."]},{"kind":"figure","head":"**평면(Plan)**, **입면(Elevation)**, **단면(Section)**","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">같은 집을 세 가지로 그려요<\/text><rect x=\"14\" y=\"46\" width=\"140\" height=\"150\" rx=\"2\" class=\"n b1\"/><rect x=\"170\" y=\"46\" width=\"140\" height=\"150\" rx=\"2\" class=\"n b2\"/><rect x=\"326\" y=\"46\" width=\"140\" height=\"150\" rx=\"2\" class=\"n b3\"/><rect x=\"30\" y=\"62\" width=\"108\" height=\"118\" rx=\"2\" class=\"n3 b1\"/><line x1=\"84.0\" y1=\"62.0\" x2=\"84.0\" y2=\"180.0\" class=\"e b1\"/><line x1=\"30.0\" y1=\"130.0\" x2=\"84.0\" y2=\"130.0\" class=\"e b1\"/><polygon points=\"180.0,110.0 240.0,66.0 300.0,110.0\" class=\"n3 b2\"/><rect x=\"186\" y=\"110\" width=\"108\" height=\"70\" rx=\"2\" class=\"n b2\"/><rect x=\"200\" y=\"124\" width=\"30\" height=\"24\" rx=\"2\" class=\"n2 b2\"/><rect x=\"250\" y=\"124\" width=\"30\" height=\"24\" rx=\"2\" class=\"n2 b2\"/><polygon points=\"336.0,110.0 396.0,66.0 456.0,110.0\" class=\"n3 b3\"/><rect x=\"342\" y=\"110\" width=\"108\" height=\"70\" rx=\"2\" class=\"n b3\"/><line x1=\"342.0\" y1=\"150.0\" x2=\"396.0\" y2=\"150.0\" class=\"e2 b3\"/><line x1=\"396.0\" y1=\"132.0\" x2=\"450.0\" y2=\"132.0\" class=\"e2 b3\"/><text x=\"84.0\" y=\"214.0\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">평면<\/text><text x=\"240.0\" y=\"214.0\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">입면<\/text><text x=\"396.0\" y=\"214.0\" font-size=\"16\" text-anchor=\"middle\" class=\"t b3\">단면<\/text><text x=\"240.0\" y=\"246.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b4\">사진에 찍히는 것은 대개 입면이에요<\/text><\/svg>","caption":"같은 집도 어디를 자르느냐에 따라 아주 다른 그림이 돼요.","builds":4},{"kind":"analogy","head":"식빵을 자르듯","scene":"식빵을 눕혀서 옆으로 자르면 넓은 면이 나오고, 세워서 자르면 속이 보여요.","map":[["눕혀 자른 넓은 면","**평면(Plan)**"],["세워 자른 속","**단면(Section)**"],["자르지 않고 본 겉","**입면(Elevation)**"]]},{"kind":"points","head":"**평면(Plan)**이 보여 주는 것","items":["방이 몇 개이고 어디에 붙어 있는지, 사람이 어디로 다니는지가 보여요.","붉은 집은 기능에 따른 불규칙한 **평면(Plan)**으로 현대 주택의 효시가 됐어요.","페레의 프랭클린가 아파트는 빛을 받으려고 변형된 U자형 **평면(Plan)**을 썼어요.","건물이 빙 둘러싼 가운데 마당이 있으면 **중정(Courtyard)**이 있는 **평면(Plan)**이에요."]},{"kind":"points","head":"**단면(Section)**이 보여 주는 것","items":["한 층의 바닥에서 위층 바닥까지의 높이가 **층고(Floor Height)**예요.","**단면(Section)**은 **층고(Floor Height)**와 높이 차이, 지붕의 모양을 보여 줘요.","바그너는 엘리베이터 덕분에 각 층의 **층고(Floor Height)**를 동일하게 평준화했어요.","바그너의 우편저축은행은 가운데가 높고 양옆이 낮은 **단면(Section)**을 가져요."]},{"kind":"figure","head":"**단면(Section)**로 보는 **라움플란(Raumplan)**","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">층고를 다르게 주면 라움플란<\/text><rect x=\"20\" y=\"50\" width=\"200\" height=\"190\" rx=\"2\" class=\"n b1\"/><line x1=\"20.0\" y1=\"110.0\" x2=\"220.0\" y2=\"110.0\" class=\"e b1\"/><line x1=\"20.0\" y1=\"170.0\" x2=\"220.0\" y2=\"170.0\" class=\"e b1\"/><text x=\"120.0\" y=\"90.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">같은 높이<\/text><text x=\"120.0\" y=\"150.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">같은 높이<\/text><text x=\"120.0\" y=\"208.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">같은 높이<\/text><rect x=\"260\" y=\"50\" width=\"200\" height=\"190\" rx=\"2\" class=\"n2 b2\"/><line x1=\"360.0\" y1=\"50.0\" x2=\"360.0\" y2=\"240.0\" class=\"e b2\"/><line x1=\"260.0\" y1=\"150.0\" x2=\"360.0\" y2=\"150.0\" class=\"e2 b3\"/><text x=\"310.0\" y=\"110.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">낮은 방<\/text><text x=\"310.0\" y=\"200.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">낮은 방<\/text><text x=\"410.0\" y=\"145.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">높은 방<\/text><text x=\"240.0\" y=\"262.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">로스는 방마다 높이를 다르게 줬어요<\/text><\/svg>","caption":"왼쪽은 층마다 **층고(Floor Height)**가 같고, 오른쪽은 방마다 달라요.","builds":4},{"kind":"points","head":"**라움플란(Raumplan)**, 높이로 설계하기","items":["로스는 '나는 **평면(Plan)**, **입면(Elevation)**, **단면(Section)**이 아니라 공간을 설계한다'고 했어요.","모든 방이 각각 특정한 **층고(Floor Height)**를 요구하므로 천장 높이를 다르게 배열한다는 뜻이에요.","한 층 안에서 바닥을 반 층씩 어긋나게 두는 스플릿 레벨을 즐겨 썼어요.","뮐러 하우스는 **라움플란(Raumplan)**이 완성된 집이에요."]},{"kind":"figure","head":"**중정(Courtyard)**이 있는 **평면(Plan)**","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">중정은 건물이 둘러싼 마당<\/text><rect x=\"90\" y=\"46\" width=\"300\" height=\"190\" rx=\"2\" class=\"n b1\"/><rect x=\"150\" y=\"86\" width=\"180\" height=\"110\" rx=\"2\" class=\"box2 b2\"/><text x=\"240.0\" y=\"146.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b2\">중정<\/text><text x=\"240.0\" y=\"68.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">주거동<\/text><text x=\"120.0\" y=\"146.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">주거동<\/text><text x=\"360.0\" y=\"146.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">주거동<\/text><text x=\"240.0\" y=\"216.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b1\">주거동<\/text><text x=\"240.0\" y=\"258.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">칼 마르크스 호프는 이 마당이 아주 커요<\/text><\/svg>","caption":"빈의 슈퍼블럭은 인간적 스케일을 벗어난 대규모 **중정(Courtyard)** 구성이에요.","builds":3},{"kind":"compare","head":"어느 그림을 봐야 하나","cols":["알고 싶은 것","봐야 할 그림"],"rows":[["겉벽의 장식과 재료","**입면(Elevation)**"],["방의 배치와 동선","**평면(Plan)**"],["**층고(Floor Height)**와 높이 차이","**단면(Section)**"],["**중정(Courtyard)**의 크기와 모양","**평면(Plan)**"]]},{"kind":"english","head":"논술 답안에 쓸 문장","en":"평면은 방의 배치를, 입면은 겉면의 구성을, 단면은 층고와 높이의 관계를 보여 준다.","ko":"세 그림의 역할을 한 문장으로 묶은 거예요.","tip":"배치, 겉면, 높이 순서로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**입면(Elevation)**은 그림이고 파사드는 실제 겉면이에요. 시험에서는 거의 같은 뜻으로 써요.","**층고(Floor Height)**는 한 방의 천장 높이가 아니라 바닥에서 위층 바닥까지예요.","**중정(Courtyard)**은 건물이 둘러싼 마당이고, 건물 앞의 빈 땅은 **중정(Courtyard)**이 아니에요."]},{"kind":"check","q":"**단면(Section)**이 뜻하는 것으로 알맞은 것은?","choices":["건물을 세로로 잘라 옆에서 들여다본 그림","건물을 가로로 잘라 내려다본 그림","건물 한 면을 정면으로 그린 그림","건물이 둘러싼 가운데 마당"],"a":0,"why":"가로로 자르면 **평면(Plan)**, 정면으로 보면 **입면(Elevation)**, 마당은 **중정(Courtyard)**이에요."},{"kind":"check","q":"로스의 **라움플란(Raumplan)**을 가장 잘 설명한 것은?","choices":["방마다 필요한 높이를 따로 주고 입체적으로 맞물리게 한다","기둥을 격자로 세워 평면을 자유롭게 한다","건물을 기둥으로 들어 올려 1층을 비운다","벽면을 3원색과 무채색으로만 칠한다"],"a":0,"why":"**라움플란(Raumplan)**는 높이의 이야기라서 **단면(Section)**을 봐야 읽혀요."},{"kind":"points","head":"이게 이 과목 어디에 나오나","items":["U1 p.23-24: 붉은 집의 불규칙한 **평면(Plan)**과 내외부가 일체화된 **평면(Plan)**.","U3 p.20, p.47, p.54: 각 층 평준화, 로스의 **라움플란(Raumplan)** 인용문, 스플릿 레벨.","U4 p.4: 페레의 변형된 U자형 **평면(Plan)**과 자유로운 평면 구성.","U5 p.2: 칼 마르크스 호프의 대규모 **중정(Courtyard)**, 곧 슈퍼블럭.","시험 모양: 평면 설명을 주고 건물을 맞히거나 O/X로 뒤집어 묻는 문제가 나와요."]},{"kind":"recap","items":["**평면(Plan)**은 가로로 잘라 내려다본 그림, 방의 배치가 보여요.","**입면(Elevation)**은 정면에서 본 그림, **단면(Section)**은 세로로 잘라 본 그림이에요.","**층고(Floor Height)**는 바닥에서 위층 바닥까지의 높이예요.","**라움플란(Raumplan)**은 방마다 높이를 다르게 주는 로스의 설계법이에요.","기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","오늘의 용어: 평면(Plan), 입면(Elevation), 단면(Section), 층고(Floor Height), 중정(Courtyard), 라움플란(Raumplan)"]}]},{"id":"wb-3","title":"기둥과 벽, 무게가 내려가는 길","goal":"**조적조(Masonry)**와 **기둥과 보(Post and Beam)**의 차이를 힘이 내려가는 길로 설명할 수 있어요.","terms":[{"ko":"기둥","en":"Column","say":"위에서 내려오는 무게를 받아 땅으로 보내는 수직 부재","more":"조적조에서는 벽이 이 일을 하고, 근대 건축에서는 기둥이 대신하면서 벽이 자유로워졌어요."},{"ko":"기둥과 보","en":"Post and Beam","say":"기둥을 세우고 그 위에 보를 걸어 무게를 받는 짜임","more":"벽이 무게를 받지 않아도 되므로 벽을 유리로 바꿀 수 있어요. 커튼월의 전제 조건이에요."},{"ko":"조적조","en":"Masonry","say":"벽돌이나 돌을 쌓아 벽 자체가 무게를 받는 구조","more":"높이 올릴수록 아래쪽 벽이 두꺼워져요. 모나드녹 빌딩은 1층 벽두께가 1.8m 예요."},{"ko":"압축","en":"Compression","say":"위에서 눌러 찌그러뜨리는 힘","more":"돌, 벽돌, 콘크리트, 주철은 압축에 강해요. 아치는 힘을 압축으로 바꿔 흘려보내는 장치예요."},{"ko":"스팬","en":"Span","say":"받침과 받침 사이, 기둥과 기둥 사이의 거리","more":"스팬이 길수록 기둥 없는 넓은 실내가 생겨요. 길게 벌린 것이 장스팬이에요."},{"ko":"커튼월","en":"curtain wall","say":"무게를 받지 않고 뼈대에 커튼처럼 걸어 놓은 바깥벽"}],"slides":[{"kind":"title","big":"기둥과 벽","sub":"무게가 어디로 내려가는지만 알면 절반은 끝나요"},{"kind":"goal","items":["**조적조(Masonry)**와 **기둥과 보(Post and Beam)**를 구별해서 말해요.","힘이 내려가는 길을 네 단계로 그려요.","왜 **커튼월(curtain wall)**이 뒤늦게야 가능해졌는지 설명해요."]},{"kind":"points","head":"앞 단원에서 이어 붙이기","items":["기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","앞에서 **파사드(Facade)**를 네 걸음으로 읽었죠. 그중 창의 크기가 힌트였어요.","창이 작고 띄엄띄엄한 이유, 창이 벽 전체로 넓어진 이유가 오늘 답이에요.","그 답은 **평면(Plan)**에도 그대로 드러나요."]},{"kind":"points","head":"**조적조(Masonry)**: 벽이 무게를 받아요","items":["벽돌이나 돌을 쌓아 벽 자체가 무게를 받는 구조가 **조적조(Masonry)**예요.","이렇게 무게를 직접 받는 벽을 **내력벽(Load-bearing Wall)**이라고 해요.","돌과 벽돌은 누르는 힘, 곧 **압축(Compression)**에는 강해서 쌓기에 알맞아요.","대신 높이 올릴수록 아래쪽 벽이 두꺼워지고 창을 크게 낼 수 없어요."]},{"kind":"figure","head":"**조적조(Masonry)**와 **기둥과 보(Post and Beam)**","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">벽이 받나요 기둥이 받나요<\/text><rect x=\"24\" y=\"46\" width=\"196\" height=\"14\" rx=\"2\" class=\"n b1\"/><rect x=\"24\" y=\"60\" width=\"44\" height=\"170\" rx=\"2\" class=\"n3 b1\"/><rect x=\"176\" y=\"60\" width=\"44\" height=\"170\" rx=\"2\" class=\"n3 b1\"/><rect x=\"34\" y=\"90\" width=\"24\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"186\" y=\"90\" width=\"24\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><text x=\"122.0\" y=\"150.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">두꺼운 벽<\/text><text x=\"122.0\" y=\"250.0\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">조적조<\/text><rect x=\"260\" y=\"46\" width=\"196\" height=\"14\" rx=\"2\" class=\"n b1\"/><rect x=\"266\" y=\"60\" width=\"14\" height=\"170\" rx=\"2\" class=\"n2 b1\"/><rect x=\"330\" y=\"60\" width=\"14\" height=\"170\" rx=\"2\" class=\"n2 b1\"/><rect x=\"394\" y=\"60\" width=\"14\" height=\"170\" rx=\"2\" class=\"n2 b1\"/><rect x=\"442\" y=\"60\" width=\"14\" height=\"170\" rx=\"2\" class=\"n2 b1\"/><rect x=\"282\" y=\"66\" width=\"46\" height=\"158\" rx=\"2\" class=\"box2 b3\"/><rect x=\"346\" y=\"66\" width=\"46\" height=\"158\" rx=\"2\" class=\"box2 b3\"/><rect x=\"410\" y=\"66\" width=\"30\" height=\"158\" rx=\"2\" class=\"box2 b3\"/><text x=\"358.0\" y=\"150.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b3\">유리 벽<\/text><text x=\"358.0\" y=\"250.0\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">기둥과 보<\/text><\/svg>","caption":"왼쪽은 벽이 **압축(Compression)**을 받고, 오른쪽은 **기둥(Column)**이 받아요.","builds":3},{"kind":"analogy","head":"어깨동무와 기둥 세우기","scene":"여럿이 어깨를 딱 붙여 서면 줄이 두꺼워지고, 몇 명만 세우면 사이가 뻥 뚫려요.","map":[["어깨를 붙여 선 줄","**조적조(Masonry)**"],["띄엄띄엄 세운 사람","**기둥과 보(Post and Beam)**"],["사람 사이의 빈 곳","창과 유리가 들어갈 자리"]]},{"kind":"points","head":"**기둥과 보(Post and Beam)**: 기둥이 무게를 받아요","items":["**기둥(Column)**을 세우고 그 위에 보를 걸어 무게를 받는 짜임이 **기둥과 보(Post and Beam)**예요.","이때 벽은 무게를 받지 않으니 **내력벽(Load-bearing Wall)**이 아니어도 돼요.","받침과 받침 사이의 거리를 **스팬(Span)**이라고 해요. **스팬(Span)**이 길수록 실내가 넓어져요.","페레는 지지하는 부재와 지지하지 않는 부재를 명확히 규정하고 드러냈어요."]},{"kind":"figure","head":"무게가 내려가는 길","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">무게가 내려가는 길<\/text><rect x=\"140\" y=\"40\" width=\"200\" height=\"34\" rx=\"2\" class=\"n3 b1\"/><text x=\"240.0\" y=\"63.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">지붕과 바닥의 무게<\/text><line x1=\"240.0\" y1=\"76.0\" x2=\"240.0\" y2=\"87.0\" class=\"e2 b2\"/><polygon points=\"240.0,96.0 235.5,87.0 244.5,87.0\" class=\"arrow b2\"/><rect x=\"140\" y=\"98\" width=\"200\" height=\"34\" rx=\"2\" class=\"n b2\"/><text x=\"240.0\" y=\"121.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">보<\/text><line x1=\"240.0\" y1=\"134.0\" x2=\"240.0\" y2=\"145.0\" class=\"e2 b3\"/><polygon points=\"240.0,154.0 235.5,145.0 244.5,145.0\" class=\"arrow b3\"/><rect x=\"140\" y=\"156\" width=\"200\" height=\"34\" rx=\"2\" class=\"n2 b3\"/><text x=\"240.0\" y=\"179.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b3\">기둥<\/text><line x1=\"240.0\" y1=\"192.0\" x2=\"240.0\" y2=\"203.0\" class=\"e2 b4\"/><polygon points=\"240.0,212.0 235.5,203.0 244.5,203.0\" class=\"arrow b4\"/><rect x=\"140\" y=\"214\" width=\"200\" height=\"34\" rx=\"2\" class=\"n3 b4\"/><text x=\"240.0\" y=\"237.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b4\">기단과 땅<\/text><text x=\"64.0\" y=\"120.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b1\">조적조라면<\/text><text x=\"64.0\" y=\"146.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b1\">이 자리가 벽<\/text><text x=\"416.0\" y=\"120.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">기둥과 보면<\/text><text x=\"416.0\" y=\"146.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">벽은 자유<\/text><text x=\"240.0\" y=\"264.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">힘은 언제나 위에서 아래로 내려가요<\/text><\/svg>","caption":"**기둥(Column)**이 받으면 벽은 무게에서 풀려요. 그 벽이 유리가 돼요.","builds":4},{"kind":"points","head":"힘이 내려가는 네 단계","items":["지붕과 바닥의 무게가 먼저 보에 실려요.","보가 받은 무게는 **기둥(Column)**으로 내려가요.","**기둥(Column)**을 지나 기단을 거쳐 땅으로 내려가요. 이 길에 걸리는 힘이 **압축(Compression)**이에요.","**조적조(Masonry)**에서는 두 번째와 세 번째 자리가 모두 벽, 곧 **내력벽(Load-bearing Wall)**이에요."]},{"kind":"points","head":"**커튼월(curtain wall)**이 태어난 순간","items":["**커튼월(curtain wall)**은 무게를 받지 않고 뼈대에 커튼처럼 걸어 놓은 바깥벽이에요.","AEG 터빈공장은 강철의 수직 지지부재에 유리벽면을 끼웠어요.","파구스 신발공장은 모서리에 **기둥(Column)**이 없고 **기둥(Column)**이 파사드 후면으로 물러났어요.","데사우 바우하우스 교사의 3층 높이 유리 **커튼월(curtain wall)**도 같은 원리예요."]},{"kind":"figure","head":"**커튼월(curtain wall)**이 가능한 까닭","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">커튼월, 벽이 짐을 내려놓아요<\/text><text x=\"240.0\" y=\"46.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">위에서 내려다본 모서리<\/text><rect x=\"60\" y=\"54\" width=\"360\" height=\"160\" rx=\"2\" class=\"box b1\"/><polyline points=\"80.0,74.0 400.0,74.0\" fill=\"none\" class=\"e2 b3\"/><polyline points=\"80.0,74.0 80.0,194.0\" fill=\"none\" class=\"e2 b3\"/><circle cx=\"120.0\" cy=\"114.0\" r=\"10\" class=\"n2 b2\"/><circle cx=\"220.0\" cy=\"114.0\" r=\"10\" class=\"n2 b2\"/><circle cx=\"320.0\" cy=\"114.0\" r=\"10\" class=\"n2 b2\"/><circle cx=\"120.0\" cy=\"174.0\" r=\"10\" class=\"n2 b2\"/><circle cx=\"220.0\" cy=\"174.0\" r=\"10\" class=\"n2 b2\"/><circle cx=\"320.0\" cy=\"174.0\" r=\"10\" class=\"n2 b2\"/><text x=\"300.0\" y=\"150.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">기둥은 안쪽으로<\/text><text x=\"190.0\" y=\"210.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">유리는 모서리를 돌아가요<\/text><text x=\"240.0\" y=\"246.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">파구스 신발공장의 모서리가 그래요<\/text><\/svg>","caption":"**기둥(Column)**이 무게를 받으니 바깥벽은 유리 커튼이 될 수 있어요.","builds":4},{"kind":"compare","head":"두 구조를 한 줄로","cols":["무엇","어떻게 되나"],"rows":[["**조적조(Masonry)**","벽이 **내력벽(Load-bearing Wall)**, 아래 벽이 두꺼워지고 창은 작아요"],["**기둥과 보(Post and Beam)**","**기둥(Column)**이 받으니 벽이 자유롭고 창이 커져요"],["모나드녹 빌딩","**조적조(Masonry)**라서 1층 벽두께가 1.8m 예요"],["홈 인슈어런스 빌딩","철골조와 **커튼월(curtain wall)**로 높이 제한이 없어졌어요"]]},{"kind":"english","head":"논술 답안에 쓸 문장","en":"조적조에서는 벽이 무게를 받지만, 기둥과 보가 무게를 받으면 벽은 커튼월이 될 수 있다.","ko":"구조가 바뀌면 겉면이 바뀐다는 이 과목의 핵심 문장이에요.","tip":"벽이 받나, 기둥이 받나 한 줄로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["모든 벽이 **내력벽(Load-bearing Wall)**은 아니에요. 무게를 받는 벽만 **내력벽(Load-bearing Wall)**이에요.","파구스는 모서리에 **기둥(Column)**이 없고, 육중한 모서리는 AEG 터빈공장이에요.","모나드녹은 **조적조(Masonry)**, 홈 인슈어런스는 철골조예요. 바꿔 묻는 문제가 나와요."]},{"kind":"check","q":"**스팬(Span)**이 뜻하는 것으로 알맞은 것은?","choices":["받침과 받침 사이의 거리","한 층의 바닥에서 위층 바닥까지의 높이","벽에 뚫은 창과 문 자리","지붕이 벽 밖으로 내민 부분"],"a":0,"why":"**스팬(Span)**이 길게 벌어진 것이 장스팬이에요. 높이는 층고, 창은 개구부예요."},{"kind":"check","q":"**커튼월(curtain wall)**이 가능해진 조건으로 가장 알맞은 것은?","choices":["기둥과 보가 무게를 모두 받아 주기 때문","벽돌을 더 단단하게 구울 수 있어서","지붕을 평지붕으로 바꿨기 때문","중정을 크게 뚫었기 때문"],"a":0,"why":"벽이 무게에서 풀려야 바깥벽을 유리 커튼으로 바꿀 수 있어요."},{"kind":"points","head":"이게 이 과목 어디에 나오나","items":["U1 p.4: 철물건축의 장점인 장스팬, 가는 **기둥(Column)**, 밝은 실내.","U2 p.54-55, p.64: 홈 인슈어런스의 철골조와 **커튼월(curtain wall)**, 모나드녹의 **조적조(Masonry)** 1.8m.","U3 p.31: 우편저축은행의 리벳 머리가 노출된 금속 **기둥(Column)**.","U4 p.4-6: 페레의 지지 부재 구분, AEG의 유리벽면, 파구스의 모서리.","시험 모양: 건물과 구조 방식을 짝지어 고르거나 O/X로 뒤집어 묻는 문제가 나와요."]},{"kind":"recap","items":["**조적조(Masonry)**는 벽이 **압축(Compression)**을 받는 구조, 그 벽이 **내력벽(Load-bearing Wall)**이에요.","**기둥과 보(Post and Beam)**에서는 **기둥(Column)**이 무게를 받아 벽이 자유로워져요.","힘의 길: 지붕과 바닥, 보, **기둥(Column)**, 기단과 땅.","받침 사이 거리가 **스팬(Span)**이고, 벽이 풀리면 **커튼월(curtain wall)**이 돼요.","기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","오늘의 용어: 기둥(Column), 기둥과 보(Post and Beam), 조적조(Masonry), 압축(Compression), 스팬(Span), 커튼월(curtain wall)"]}]},{"id":"wb-4","title":"아치와 볼트와 돔","goal":"**아치(Arch)**와 **볼트(Vault)**와 **돔 지붕(Dome)**의 관계를 재료의 성질로 설명할 수 있어요.","terms":[{"ko":"아치","en":"Arch","say":"개구부 위를 곡선으로 쌓아 무게를 양옆으로 흘려보내는 구조","more":"평평한 인방은 아래쪽이 당겨져서 길게 걸 수 없어요. 아치는 그 당김을 누름으로 바꿔 줘요."},{"ko":"볼트","en":"Vault","say":"아치를 한 방향으로 쭉 밀고 나간 터널 모양 천장","more":"정리노트와 강의는 배럴 보울트라고 적어요. 우편저축은행 주 업무실 지붕이 그 예예요."},{"ko":"돔 지붕","en":"Dome","say":"아치를 한 점 둘레로 빙 돌려 만든 반구 모양 지붕","more":"쁘렝땅 백화점의 천장 유리 돔, 분리파 전시관의 금색 월계수 잎 돔이 이 과목의 예예요."},{"ko":"인장","en":"Tension","say":"양쪽에서 잡아당겨 늘이는 힘","more":"돌과 벽돌과 콘크리트는 인장에 약해요. 철골과 철근이 이 약점을 메워 주었어요."},{"ko":"압축","en":"Compression","say":"위에서 눌러 찌그러뜨리는 힘","more":"돌, 벽돌, 콘크리트, 주철은 압축에 강해요. 아치는 힘을 압축으로 바꿔 흘려보내는 장치예요."},{"ko":"트러스","en":"Truss","say":"삼각형을 이어 붙여 긴 거리를 가볍게 건너는 뼈대","more":"삼각형은 모양이 안 변해서 가벼운 재료로도 넓은 지붕을 덮을 수 있어요. AEG 터빈공장 내부가 아치형 트러스예요."},{"ko":"스팬","en":"Span","say":"받침과 받침 사이, 기둥과 기둥 사이의 거리","more":"스팬이 길수록 기둥 없는 넓은 실내가 생겨요. 길게 벌린 것이 장스팬이에요."}],"slides":[{"kind":"title","big":"아치 볼트 돔","sub":"셋은 한 식구예요. 미는 방향만 달라요"},{"kind":"goal","items":["**아치(Arch)**가 왜 필요했는지 재료의 성질로 말해요.","**아치(Arch)**와 **볼트(Vault)**와 **돔 지붕(Dome)**의 관계를 그림으로 그려요.","이 과목 건물에서 셋을 찾아 이름을 대요."]},{"kind":"points","head":"앞 단원에서 이어 붙이기","items":["기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","앞에서 **조적조(Masonry)**는 벽이 무게를 받는 구조라고 했죠.","그 벽에 구멍을 뚫으려면 구멍 위의 무게를 어딘가로 보내야 해요.","**기둥(Column)**이 없던 시절, 그 답이 **아치(Arch)**였어요."]},{"kind":"points","head":"누르는 힘과 당기는 힘","items":["위에서 눌러 찌그러뜨리는 힘이 **압축(Compression)**이에요.","양쪽에서 잡아당겨 늘이는 힘이 **인장(Tension)**이에요.","돌, 벽돌, 콘크리트는 **압축(Compression)**에 강하고 **인장(Tension)**에 약해요.","평평한 부재를 길게 걸면 아래쪽이 **인장(Tension)**을 받아 부러져요."]},{"kind":"figure","head":"**아치(Arch)**가 필요한 까닭","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">평평한 인방과 아치의 차이<\/text><rect x=\"30\" y=\"60\" width=\"180\" height=\"170\" rx=\"2\" class=\"n b1\"/><rect x=\"70\" y=\"130\" width=\"100\" height=\"100\" rx=\"2\" class=\"box2 b1\"/><rect x=\"64\" y=\"116\" width=\"112\" height=\"14\" rx=\"2\" class=\"n3 b2\"/><line x1=\"120.0\" y1=\"84.0\" x2=\"120.0\" y2=\"103.0\" class=\"e2 b2\"/><polygon points=\"120.0,112.0 115.5,103.0 124.5,103.0\" class=\"arrow b2\"/><text x=\"120.0\" y=\"250.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">인방은 아래가 당겨져요<\/text><rect x=\"270\" y=\"60\" width=\"180\" height=\"170\" rx=\"2\" class=\"n b1\"/><path d=\"M310 230 L310 160 A50 50 0 0 1 410 160 L410 230\" fill=\"none\" class=\"e2 b3\"/><line x1=\"360.0\" y1=\"84.0\" x2=\"360.0\" y2=\"95.0\" class=\"e2 b3\"/><polygon points=\"360.0,104.0 355.5,95.0 364.5,95.0\" class=\"arrow b3\"/><line x1=\"360.0\" y1=\"140.0\" x2=\"329.4\" y2=\"160.9\" class=\"e2 b4\"/><polygon points=\"322.0,166.0 326.9,157.2 332.0,164.6\" class=\"arrow b4\"/><line x1=\"360.0\" y1=\"140.0\" x2=\"390.6\" y2=\"160.9\" class=\"e2 b4\"/><polygon points=\"398.0,166.0 388.0,164.6 393.1,157.2\" class=\"arrow b4\"/><text x=\"360.0\" y=\"250.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">아치는 옆으로 흘려보내요<\/text><\/svg>","caption":"돌과 벽돌은 **인장(Tension)**에 약해요. **아치(Arch)**는 그 당김을 누름으로 바꿔요.","builds":4},{"kind":"analogy","head":"줄다리기와 아치","scene":"줄은 당기면 버티고 누르면 힘을 못 써요. 돌은 정반대로 눌러야 버텨요.","map":[["당겨야 버티는 줄","**인장(Tension)**"],["눌러야 버티는 돌","**압축(Compression)**"],["당김을 누름으로 바꾸는 장치","**아치(Arch)**"]]},{"kind":"points","head":"**아치(Arch)**, **볼트(Vault)**, **돔 지붕(Dome)**","items":["**아치(Arch)**는 개구부 위를 곡선으로 쌓아 무게를 양옆으로 흘려보내요.","**아치(Arch)**를 한 방향으로 쭉 밀고 나가면 터널 모양 **볼트(Vault)**가 돼요.","**아치(Arch)**를 한 점 둘레로 빙 돌리면 반구 모양 **돔 지붕(Dome)**이 돼요.","그래서 기둥 없이도 넓은 **스팬(Span)**을 건널 수 있어요."]},{"kind":"figure","head":"**아치(Arch)**, **볼트(Vault)**, **돔 지붕(Dome)**","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">아치와 볼트와 돔 지붕<\/text><rect x=\"14\" y=\"46\" width=\"140\" height=\"150\" rx=\"2\" class=\"n b1\"/><rect x=\"170\" y=\"46\" width=\"140\" height=\"150\" rx=\"2\" class=\"n b2\"/><rect x=\"326\" y=\"46\" width=\"140\" height=\"150\" rx=\"2\" class=\"n b3\"/><path d=\"M44 170 L44 120 A40 40 0 0 1 124 120 L124 170\" fill=\"none\" class=\"e2 b1\"/><path d=\"M196 172 L196 122 A40 40 0 0 1 276 122 L276 172\" fill=\"none\" class=\"e2 b2\"/><path d=\"M216 152 L216 102 A40 40 0 0 1 296 102\" fill=\"none\" class=\"e b2\"/><line x1=\"196.0\" y1=\"122.0\" x2=\"216.0\" y2=\"102.0\" class=\"e b2\"/><line x1=\"276.0\" y1=\"122.0\" x2=\"296.0\" y2=\"102.0\" class=\"e b2\"/><path d=\"M356 150 A40 40 0 0 1 436 150\" fill=\"none\" class=\"e2 b3\"/><path d=\"M356 150 A40 12 0 0 0 436 150\" fill=\"none\" class=\"e b3\"/><text x=\"84.0\" y=\"214.0\" font-size=\"16\" text-anchor=\"middle\" class=\"t b1\">아치<\/text><text x=\"240.0\" y=\"214.0\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">볼트<\/text><text x=\"396.0\" y=\"214.0\" font-size=\"16\" text-anchor=\"middle\" class=\"t b3\">돔 지붕<\/text><text x=\"240.0\" y=\"246.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">아치를 밀면 볼트, 돌리면 돔 지붕<\/text><\/svg>","caption":"셋은 남남이 아니라 한 식구예요. 미는 방향만 달라요.","builds":4},{"kind":"points","head":"이 과목에 나오는 사례","items":["바그너의 우편저축은행은 노출 메탈과 유리로 만든 배럴 보울트 지붕을 써요.","쁘렝땅 백화점은 천장 유리 **돔 지붕(Dome)**을 스테인드글라스로 장식했어요.","설리번의 개런티 트러스트 빌딩은 애틱 하부까지 **아치(Arch)**를 밀어올려 수직성을 강조해요.","베델 주거단지는 1층 저층부에 벽돌 **아치(Arch)**를 두었어요."]},{"kind":"figure","head":"**아치(Arch)**를 수직으로 올린 에펠탑","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">아치를 세로로 세우면 탑이 돼요<\/text><path d=\"M150 240 L150 200 A90 40 0 0 1 330 200 L330 240\" fill=\"none\" class=\"e2 b1\"/><line x1=\"150.0\" y1=\"240.0\" x2=\"190.0\" y2=\"120.0\" class=\"e b1\"/><line x1=\"330.0\" y1=\"240.0\" x2=\"290.0\" y2=\"120.0\" class=\"e b1\"/><line x1=\"186.0\" y1=\"130.0\" x2=\"294.0\" y2=\"130.0\" class=\"e b2\"/><line x1=\"190.0\" y1=\"120.0\" x2=\"206.0\" y2=\"70.0\" class=\"e b2\"/><line x1=\"290.0\" y1=\"120.0\" x2=\"274.0\" y2=\"70.0\" class=\"e b2\"/><line x1=\"204.0\" y1=\"76.0\" x2=\"276.0\" y2=\"76.0\" class=\"e b3\"/><line x1=\"206.0\" y1=\"70.0\" x2=\"240.0\" y2=\"40.0\" class=\"e b3\"/><line x1=\"274.0\" y1=\"70.0\" x2=\"240.0\" y2=\"40.0\" class=\"e b3\"/><text x=\"90.0\" y=\"215.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">기단<\/text><text x=\"380.0\" y=\"125.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">몸통<\/text><text x=\"380.0\" y=\"60.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b3\">탑<\/text><text x=\"240.0\" y=\"266.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">기단, 몸통, 탑으로 이루어져요<\/text><\/svg>","caption":"에펠은 다리에서 쌓은 실력으로 **아치(Arch)** 기술을 수직으로 올렸어요.","builds":4},{"kind":"points","head":"**트러스(Truss)**, 삼각형으로 건너기","items":["삼각형을 이어 붙여 긴 거리를 가볍게 건너는 뼈대가 **트러스(Truss)**예요.","삼각형은 모양이 잘 안 변해서 가벼운 재료로도 큰 **스팬(Span)**을 건너요.","AEG 터빈공장의 내부는 아치형 **트러스(Truss)**로 지지돼요.","**트러스(Truss)**는 **인장(Tension)**에 강한 철이 있어야 제 힘을 내요."]},{"kind":"compare","head":"셋을 한 줄로","cols":["이름","만드는 법"],"rows":[["**아치(Arch)**","구멍 위를 곡선으로 쌓아 **압축(Compression)**으로 흘려보내요"],["**볼트(Vault)**","**아치(Arch)**를 한 방향으로 밀고 나가요"],["**돔 지붕(Dome)**","**아치(Arch)**를 한 점 둘레로 돌려요"],["**트러스(Truss)**","삼각형을 이어 붙여 긴 **스팬(Span)**을 건너요"]]},{"kind":"english","head":"논술 답안에 쓸 문장","en":"돌과 벽돌은 압축에 강하고 인장에 약하므로, 아치로 힘을 압축으로 바꾸어 넓은 구멍을 덮었다.","ko":"재료의 성질에서 형태가 나온다는 설명이에요.","tip":"약점, 해결, 결과 순서로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**아치(Arch)**를 밀면 **볼트(Vault)**, 돌리면 **돔 지붕(Dome)**이에요. 바꿔 묻는 문제가 나와요.","강의와 정리노트는 우편저축은행 지붕을 배럴 보울트라고 적어요.","AEG의 아치형 **트러스(Truss)**는 **아치(Arch)** 자체가 아니라 아치 모양의 뼈대예요."]},{"kind":"check","q":"**볼트(Vault)**가 뜻하는 것으로 알맞은 것은?","choices":["아치를 한 방향으로 밀고 나간 터널 모양 천장","아치를 한 점 둘레로 돌린 반구 모양 지붕","삼각형을 이어 붙인 가벼운 뼈대","창 위에 가로로 걸친 평평한 부재"],"a":0,"why":"돌린 것은 **돔 지붕(Dome)**, 삼각형은 **트러스(Truss)**, 평평한 부재는 인방이에요."},{"kind":"check","q":"돌로 넓은 구멍을 덮을 때 **아치(Arch)**가 유리한 까닭은?","choices":["약한 **인장(Tension)**을 피하고 **압축(Compression)**으로 힘을 흘려보내기 때문","돌의 **인장(Tension)**을 키워 주기 때문","벽을 더 두껍게 쌓을 수 있기 때문","지붕을 평평하게 만들 수 있기 때문"],"a":0,"why":"**아치(Arch)**는 힘의 방향을 바꿔 주는 장치예요."},{"kind":"points","head":"이게 이 과목 어디에 나오나","items":["U1 p.7: 에펠탑이 **아치(Arch)** 기술을 수직으로 올리고 기단, 몸통, 탑으로 구성.","U2 p.59: 개런티 트러스트 빌딩이 애틱 하부까지 **아치(Arch)**를 밀어올려 수직성 강조.","U3 p.30: 우편저축은행 주 업무실의 배럴 보울트 지붕과 구조용 유리 바닥.","U4 p.5, U6 p.14: AEG의 아치형 **트러스(Truss)**, 베델 주거단지 1층의 벽돌 **아치(Arch)**.","시험 모양: 지붕 형식과 건물을 짝짓거나 단답으로 이름을 쓰게 해요."]},{"kind":"recap","items":["**아치(Arch)**는 구멍 위의 무게를 곡선으로 양옆에 넘겨요.","밀면 **볼트(Vault)**, 돌리면 **돔 지붕(Dome)**이에요.","돌은 **압축(Compression)**에 강하고 **인장(Tension)**에 약해요.","**트러스(Truss)**는 삼각형으로 긴 **스팬(Span)**을 건너는 뼈대예요.","기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","오늘의 용어: 아치(Arch), 볼트(Vault), 돔 지붕(Dome), 인장(Tension), 압축(Compression), 트러스(Truss), 스팬(Span)"]}]},{"id":"wb-5","title":"철과 유리가 바꾼 것","goal":"**주철(cast iron)**와 **단철(wrought iron)**과 **철골(강철)(steel)**을 구별하고 철과 유리가 무엇을 바꿨는지 말할 수 있어요.","terms":[{"ko":"주철","en":"cast iron","say":"탄소가 많아 압축에 강하지만 부러지기 쉬운 철","more":"주철, 단철, 강철 구분: 주철은 잘 부러짐, 단철은 잘 늘어남, 강철은 다 강함."},{"ko":"단철","en":"wrought iron","say":"탄소가 적어 잘 늘어나는 철"},{"ko":"철골(강철)","en":"steel","say":"인장과 압축에 모두 강한 근대 재료","more":"1709년 발명되어 공업 재료로 쓰이다 1820년경 건축에 도입, 1870년을 기점으로 사용량이 크게 늘어남."},{"ko":"판유리","en":"Plate Glass","say":"크고 평평하게 만든 유리판","more":"값싼 유리가 보급되면서 넓은 창문이 가능해졌고, 나중에는 벽 전체가 유리가 되었어요."},{"ko":"장스팬","en":"","say":"기둥과 기둥 사이를 길게 벌린 구조","more":"철 건축의 장점 세트: 장스팬, 가는 기둥, 밝은 실내."},{"ko":"커튼월","en":"curtain wall","say":"무게를 받지 않고 뼈대에 커튼처럼 걸어 놓은 바깥벽"}],"slides":[{"kind":"title","big":"철과 유리","sub":"19세기의 두 신재료가 건물을 통째로 바꿔요"},{"kind":"goal","items":["**주철(cast iron)**, **단철(wrought iron)**, **철골(강철)(steel)**의 성질을 갈라서 말해요.","철 건축의 장점 세 단어와 새 건물 유형을 대요.","**판유리(Plate Glass)**가 늘어나며 벽이 어떻게 바뀌었는지 설명해요."]},{"kind":"points","head":"앞 단원에서 이어 붙이기","items":["기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","앞에서 돌과 벽돌은 **압축(Compression)**에 강하고 **인장(Tension)**에 약하다고 했죠.","그 약점 때문에 아치가 필요했어요. 그런데 철은 **인장(Tension)**에도 강해요.","그래서 곧은 보만으로도 넓은 곳을 건널 수 있게 됐어요."]},{"kind":"points","head":"19세기의 두 신재료","items":["19세기 신건축운동은 철물과 철근콘크리트를 매개로 성립하고 발전했어요.","**주철(cast iron)**, **단철(wrought iron)**, **철골(강철)(steel)**의 철물 건축이 주축이 됐어요.","**철골(강철)(steel)**은 1709년 발명되어 공업 재료로 쓰이다가 1820년경 건축에 들어왔어요.","1870년을 기점으로 사용량이 크게 늘었어요. 프랑스는 실험, 영국은 실용이에요."]},{"kind":"figure","head":"철 3형제","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">철 3형제와 잘 버티는 힘<\/text><rect x=\"14\" y=\"48\" width=\"148\" height=\"54\" rx=\"2\" class=\"n3 b1\"/><text x=\"88.0\" y=\"72.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b1\">주철<\/text><text x=\"88.0\" y=\"92.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b1\">압축에 강함<\/text><rect x=\"166\" y=\"48\" width=\"148\" height=\"54\" rx=\"2\" class=\"n b2\"/><text x=\"240.0\" y=\"72.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b2\">단철<\/text><text x=\"240.0\" y=\"92.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b2\">잘 늘어남<\/text><rect x=\"318\" y=\"48\" width=\"148\" height=\"54\" rx=\"2\" class=\"n2 b3\"/><text x=\"392.0\" y=\"72.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b3\">철골(강철)<\/text><text x=\"392.0\" y=\"92.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">둘 다 강함<\/text><rect x=\"70\" y=\"176\" width=\"120\" height=\"24\" rx=\"2\" class=\"n3 b4\"/><line x1=\"130.0\" y1=\"150.0\" x2=\"130.0\" y2=\"163.0\" class=\"e2 b4\"/><polygon points=\"130.0,172.0 125.5,163.0 134.5,163.0\" class=\"arrow b4\"/><line x1=\"130.0\" y1=\"226.0\" x2=\"130.0\" y2=\"213.0\" class=\"e2 b4\"/><polygon points=\"130.0,204.0 134.5,213.0 125.5,213.0\" class=\"arrow b4\"/><text x=\"130.0\" y=\"144.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b4\">누르는 힘<\/text><text x=\"130.0\" y=\"248.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b4\">압축<\/text><rect x=\"290\" y=\"176\" width=\"120\" height=\"24\" rx=\"2\" class=\"n3 b4\"/><line x1=\"288.0\" y1=\"188.0\" x2=\"263.0\" y2=\"188.0\" class=\"e2 b4\"/><polygon points=\"254.0,188.0 263.0,183.5 263.0,192.5\" class=\"arrow b4\"/><line x1=\"412.0\" y1=\"188.0\" x2=\"437.0\" y2=\"188.0\" class=\"e2 b4\"/><polygon points=\"446.0,188.0 437.0,192.5 437.0,183.5\" class=\"arrow b4\"/><text x=\"350.0\" y=\"144.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b4\">당기는 힘<\/text><text x=\"350.0\" y=\"248.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b4\">인장<\/text><\/svg>","caption":"**주철(cast iron)**은 압축, **단철(wrought iron)**은 늘어남, **철골(강철)(steel)**은 둘 다예요.","builds":4},{"kind":"analogy","head":"세 형제로 보면","scene":"딱딱하지만 잘 부러지는 형, 잘 늘어나는 형, 당겨도 눌러도 다 버티는 막내가 있어요.","map":[["딱딱하고 잘 부러지는 형","**주철(cast iron)**"],["잘 늘어나는 형","**단철(wrought iron)**"],["다 버티는 막내","**철골(강철)(steel)**"]]},{"kind":"points","head":"철 건축의 장점 세 단어","items":["**장스팬**, 곧 기둥과 기둥 사이를 길게 벌린 구조예요.","가는 기둥이에요. 철이라 얇아도 버텨요.","밝은 실내예요. 벽을 유리로 바꿀 수 있어요.","**장스팬** 덕분에 기차역, 전시관, 박물관, 백화점, 온실이 가능해졌어요."]},{"kind":"figure","head":"**장스팬**이 길어져요","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">돌로는 짧게, 철로는 길게<\/text><rect x=\"40\" y=\"120\" width=\"24\" height=\"100\" rx=\"2\" class=\"n3 b1\"/><rect x=\"140\" y=\"120\" width=\"24\" height=\"100\" rx=\"2\" class=\"n3 b1\"/><rect x=\"240\" y=\"120\" width=\"24\" height=\"100\" rx=\"2\" class=\"n3 b1\"/><rect x=\"40\" y=\"104\" width=\"224\" height=\"16\" rx=\"2\" class=\"n3 b1\"/><text x=\"152.0\" y=\"90.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b1\">스팬이 짧아요<\/text><rect x=\"300\" y=\"120\" width=\"16\" height=\"100\" rx=\"2\" class=\"n2 b2\"/><rect x=\"440\" y=\"120\" width=\"16\" height=\"100\" rx=\"2\" class=\"n2 b2\"/><polyline points=\"300.0,104.0 456.0,104.0\" fill=\"none\" class=\"e2 b2\"/><polyline points=\"300.0,80.0 456.0,80.0\" fill=\"none\" class=\"e2 b2\"/><polyline points=\"300.0,104.0 322.0,80.0 344.0,104.0 366.0,80.0 388.0,104.0 410.0,80.0 432.0,104.0 454.0,80.0\" fill=\"none\" class=\"e b3\"/><text x=\"378.0\" y=\"66.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b2\">긴 스팬<\/text><text x=\"102.0\" y=\"232.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b1\">돌과 벽돌<\/text><text x=\"378.0\" y=\"232.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b2\">철과 트러스<\/text><text x=\"240.0\" y=\"250.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b4\">기둥과 기둥 사이가 스팬이에요<\/text><\/svg>","caption":"철이 오자 기둥은 가늘어지고 사이는 넓어졌어요.","builds":4},{"kind":"points","head":"**판유리(Plate Glass)**가 바꾼 것","items":["**판유리(Plate Glass)**는 크고 평평하게 만든 유리판이에요.","산업혁명으로 유리와 콘크리트가 대량생산됐고 값싼 유리가 보급됐어요.","그래서 넓은 창문을 달게 되고 전통적인 비례체계가 무시됐어요.","벽이 무게에서 풀린 뒤에는 벽 전체가 **판유리(Plate Glass)**, 곧 **커튼월(curtain wall)**이 됐어요."]},{"kind":"figure","head":"철과 **판유리(Plate Glass)**가 만든 고층 건물","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">시카고 창과 3단 구성<\/text><rect x=\"40\" y=\"70\" width=\"200\" height=\"120\" rx=\"2\" class=\"n b1\"/><rect x=\"46\" y=\"76\" width=\"40\" height=\"108\" rx=\"2\" class=\"n2 b2\"/><rect x=\"90\" y=\"76\" width=\"100\" height=\"108\" rx=\"2\" class=\"n3 b2\"/><rect x=\"194\" y=\"76\" width=\"40\" height=\"108\" rx=\"2\" class=\"n2 b2\"/><text x=\"140.0\" y=\"210.0\" font-size=\"16\" text-anchor=\"middle\" class=\"t b2\">시카고 창<\/text><text x=\"140.0\" y=\"238.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">셋으로 나뉘고 돌출<\/text><rect x=\"300\" y=\"60\" width=\"140\" height=\"30\" rx=\"2\" class=\"n3 b4\"/><rect x=\"300\" y=\"90\" width=\"140\" height=\"100\" rx=\"2\" class=\"n b4\"/><rect x=\"300\" y=\"190\" width=\"140\" height=\"40\" rx=\"2\" class=\"n3 b4\"/><text x=\"370.0\" y=\"80.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b4\">주두<\/text><text x=\"370.0\" y=\"145.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b4\">몸통<\/text><text x=\"370.0\" y=\"214.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b4\">기단<\/text><text x=\"370.0\" y=\"252.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">베이스, 바디, 코니스<\/text><\/svg>","caption":"시카고 학파 고층 건물은 철골에 테라코타 외벽, 3부분 분할, 시카고 창이에요.","builds":4},{"kind":"points","head":"철과 유리가 만든 새 건물","items":["수정궁은 1851년 런던 전시관으로 건물 전체를 유리만으로 시공했어요.","갤러리 형 박물관은 중앙 로비 채광을 위해 천장을 철물과 유리로 덮었어요.","시카고에서는 주철 골조 1850년, 증기엘리베이터 1864년, 수력엘리베이터 1867년이에요.","강철 구조로 고층화가 되고 백화점과 사무실에 큰 창이 생겼어요."]},{"kind":"compare","head":"철 3형제 한 줄 정리","cols":["이름","성질"],"rows":[["**주철(cast iron)**","탄소가 많아 **압축(Compression)**에 강하지만 부러지기 쉬워요"],["**단철(wrought iron)**","탄소가 적어 잘 늘어나요"],["**철골(강철)(steel)**","인장과 압축에 모두 강한 근대 재료예요"],["**판유리(Plate Glass)**","벽을 열어 밝은 실내와 **커튼월(curtain wall)**을 만들어요"]]},{"kind":"english","head":"논술 답안에 쓸 문장","en":"철물건축은 주철과 단철과 철골을 주축으로 하며, 장스팬과 가는 기둥과 밝은 실내를 특징으로 한다.","ko":"재료 셋과 장점 셋을 한 문장에 담았어요.","tip":"형제 셋, 장점 셋으로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**주철(cast iron)**은 압축에 강하고, 인장과 압축에 모두 강한 것은 **철골(강철)(steel)**이에요.","**철골(강철)(steel)**은 1709년 발명이지만 건축 도입은 1820년경이에요. 붙여 쓰면 틀려요.","시카고 창은 셋으로 나뉜 격자이고 돌출돼요. 마름모 창은 베델 주거단지예요."]},{"kind":"check","q":"**장스팬**이 뜻하는 것으로 알맞은 것은?","choices":["기둥과 기둥 사이를 길게 벌린 구조","천장을 유리로 덮은 구조","벽을 두껍게 쌓은 구조","기둥을 촘촘히 세운 구조"],"a":0,"why":"**장스팬**과 가는 기둥, 밝은 실내가 철물건축의 장점 세 단어예요."},{"kind":"check","q":"**판유리(Plate Glass)**가 늘어나며 생긴 변화로 알맞은 것은?","choices":["넓은 창문이 생기고 전통적인 비례체계가 무시됐다","벽이 더 두꺼워지고 창이 작아졌다","지붕이 급경사로 바뀌었다","장식이 더 화려해졌다"],"a":0,"why":"값싼 유리 보급이 넓은 창문을 낳았고, 나중에는 벽 전체가 **커튼월(curtain wall)**이 됐어요."},{"kind":"points","head":"이게 이 과목 어디에 나오나","items":["U1 p.4: **주철(cast iron)**, **단철(wrought iron)**, **철골(강철)(steel)**과 장스팬, 가는 기둥, 밝은 실내.","U1 p.5, p.7, p.10: 갤러리 형의 유리 천장, 수정궁과 에펠탑, 팜 하우스.","U2 p.3: 값싼 유리 보급에 따른 넓은 창문과 비례체계 무시.","U2 p.52, p.64: 시카고의 강철 구조와 엘리베이터, 시카고 창.","시험 모양: 연도와 재료를 짝짓는 단답, 철 3형제를 가르는 O/X 가 자주 나와요."]},{"kind":"recap","items":["19세기의 두 신재료는 철물과 철근콘크리트예요.","**주철(cast iron)**은 압축, **단철(wrought iron)**은 늘어남, **철골(강철)(steel)**은 둘 다예요.","장점 세 단어는 **장스팬**, 가는 기둥, 밝은 실내예요.","**판유리(Plate Glass)**가 넓어지며 벽이 **커튼월(curtain wall)**으로 바뀌었어요.","기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","오늘의 용어: 주철(cast iron), 단철(wrought iron), 철골(강철)(steel), 판유리(Plate Glass), 장스팬, 커튼월(curtain wall)"]}]},{"id":"wb-6","title":"철근콘크리트와 새 몸짓","goal":"**철근콘크리트(Reinforced Concrete)**가 무엇이고 **캔틸레버(cantilever)**와 **필로티(Pilotis)**를 어떻게 가능하게 했는지 말할 수 있어요.","terms":[{"ko":"철근콘크리트","en":"Reinforced Concrete","say":"콘크리트 안에 철근을 넣어 누름과 당김을 함께 버티게 한 재료","more":"콘크리트는 압축에 강하고 인장에 약해서, 당겨지는 자리에 철근을 넣어요. 철물과 함께 19세기의 두 신재료예요."},{"ko":"캔틸레버","en":"cantilever","say":"한쪽 끝만 고정하고 다른 끝은 받침 없이 내민 구조"},{"ko":"필로티","en":"Pilotis","say":"건물을 기둥으로 들어 올려 아래를 비우는 방식","more":"르 코르뷔지에가 바이센호프에서 개방적인 평면 개념과 함께 제시."},{"ko":"평지붕","en":"Flat Roof","say":"바이센호프 주택들이 공통으로 쓴 평평한 지붕"},{"ko":"조소성","en":"","say":"굳기 전 찰흙처럼 모양을 빚을 수 있는 콘크리트의 성질"},{"ko":"인장","en":"Tension","say":"양쪽에서 잡아당겨 늘이는 힘","more":"돌과 벽돌과 콘크리트는 인장에 약해요. 철골과 철근이 이 약점을 메워 주었어요."}],"slides":[{"kind":"title","big":"철근콘크리트","sub":"굳기 전에는 찰흙, 굳으면 돌, 속에는 철"},{"kind":"goal","items":["**철근콘크리트(Reinforced Concrete)**가 무엇인지 재료의 성질로 설명해요.","**캔틸레버(cantilever)**와 **필로티(Pilotis)**와 **평지붕(Flat Roof)**이 왜 같이 다니는지 말해요.","이 과목에서 콘크리트를 쓴 건물을 세 개 이상 대요."]},{"kind":"points","head":"앞 단원에서 이어 붙이기","items":["기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","앞에서 **철골(강철)(steel)**은 인장과 압축에 모두 강하다고 했죠.","**판유리(Plate Glass)**는 벽을 열어 밝은 실내를 만들어 줬고요.","이제 두 번째 신재료 차례예요. 콘크리트에 철을 넣은 재료예요."]},{"kind":"points","head":"**철근콘크리트(Reinforced Concrete)**가 무엇인가요","items":["콘크리트는 누르는 힘에는 강하지만 **인장(Tension)**에는 약해요.","그래서 당겨지는 자리에 철근을 넣은 것이 **철근콘크리트(Reinforced Concrete)**예요.","19세기 신건축운동은 철물과 **철근콘크리트(Reinforced Concrete)**를 두 신재료로 삼았어요.","굳기 전에는 거푸집 모양대로 흘러 들어가니 형태가 아주 자유로워요."]},{"kind":"figure","head":"**철근콘크리트(Reinforced Concrete)**가 버티는 법","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">콘크리트에 철근을 넣어요<\/text><rect x=\"60\" y=\"100\" width=\"360\" height=\"60\" rx=\"2\" class=\"n3 b1\"/><rect x=\"60\" y=\"160\" width=\"40\" height=\"60\" rx=\"2\" class=\"n2 b1\"/><rect x=\"380\" y=\"160\" width=\"40\" height=\"60\" rx=\"2\" class=\"n2 b1\"/><line x1=\"240.0\" y1=\"70.0\" x2=\"240.0\" y2=\"87.0\" class=\"e2 b2\"/><polygon points=\"240.0,96.0 235.5,87.0 244.5,87.0\" class=\"arrow b2\"/><text x=\"160.0\" y=\"86.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b2\">위에서 누름<\/text><text x=\"240.0\" y=\"124.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">콘크리트<\/text><line x1=\"76.0\" y1=\"146.0\" x2=\"404.0\" y2=\"146.0\" class=\"e2 b3\"/><text x=\"150.0\" y=\"180.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">여기가 당겨져요<\/text><text x=\"310.0\" y=\"180.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">철근은 아래쪽에<\/text><text x=\"240.0\" y=\"244.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">압축은 콘크리트, 인장은 철근이 버텨요<\/text><\/svg>","caption":"콘크리트는 **압축(Compression)**에 강하고 **인장(Tension)**에 약해요. 그 자리에 철근을 넣어요.","builds":4},{"kind":"analogy","head":"찰흙 속의 철사","scene":"찰흙만으로 길쭉한 막대를 만들면 뚝 부러지지만, 속에 철사를 넣으면 버텨요.","map":[["찰흙","콘크리트"],["속에 넣은 철사","철근"],["부러지는 아래쪽","**인장(Tension)**을 받는 자리"]]},{"kind":"points","head":"**캔틸레버(cantilever)**, 한쪽만 붙잡기","items":["한쪽 끝만 고정하고 다른 끝은 받침 없이 내민 구조가 **캔틸레버(cantilever)**예요.","내민 부분은 위쪽이 당겨지므로 **인장(Tension)**에 강한 재료가 있어야 해요.","페레의 프랭클린가 아파트는 **캔틸레버(cantilever)**를 적용해 저층부를 개방적으로 만들었어요.","전면 파사드를 대담하게 돌출 또는 후퇴시켜 자유로운 평면을 구성했어요."]},{"kind":"figure","head":"**캔틸레버(cantilever)**, 한쪽만 붙잡는 구조","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">캔틸레버는 한쪽만 붙잡아요<\/text><rect x=\"60\" y=\"60\" width=\"60\" height=\"180\" rx=\"2\" class=\"n3 b1\"/><rect x=\"120\" y=\"120\" width=\"260\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><line x1=\"300.0\" y1=\"74.0\" x2=\"300.0\" y2=\"107.0\" class=\"e2 b3\"/><polygon points=\"300.0,116.0 295.5,107.0 304.5,107.0\" class=\"arrow b3\"/><polyline points=\"120.0,160.0 250.0,168.0 380.0,182.0\" fill=\"none\" class=\"e b4\"/><text x=\"90.0\" y=\"220.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">고정<\/text><text x=\"250.0\" y=\"136.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">내민 부분<\/text><text x=\"300.0\" y=\"94.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">위에서 누름<\/text><text x=\"300.0\" y=\"204.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">끝은 받침이 없어요<\/text><text x=\"240.0\" y=\"252.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">페레의 프랭클린가 아파트가 이 구조를 썼어요<\/text><\/svg>","caption":"받침 없이 내밀려면 **인장(Tension)**을 버티는 재료가 있어야 해요.","builds":4},{"kind":"points","head":"**필로티(Pilotis)**와 **평지붕(Flat Roof)**","items":["건물을 기둥으로 들어 올려 아래를 비우는 방식이 **필로티(Pilotis)**예요.","바이센호프 주거단지에서 르 코르뷔지에가 **필로티(Pilotis)**와 개방적인 평면을 보여 줬어요.","그 단지의 공통점은 장식 없는 깨끗한 벽면, **평지붕(Flat Roof)**, 자유로운 입면이에요.","**평지붕(Flat Roof)**은 처마와 인방이 사라진 매끈한 얼굴과 짝을 이뤄요."]},{"kind":"figure","head":"**필로티(Pilotis)**가 만드는 1층","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">필로티는 1층을 비워요<\/text><rect x=\"80\" y=\"54\" width=\"320\" height=\"120\" rx=\"2\" class=\"n b1\"/><rect x=\"100\" y=\"70\" width=\"60\" height=\"40\" rx=\"2\" class=\"n2 b2\"/><rect x=\"180\" y=\"70\" width=\"60\" height=\"40\" rx=\"2\" class=\"n2 b2\"/><rect x=\"260\" y=\"70\" width=\"60\" height=\"40\" rx=\"2\" class=\"n2 b2\"/><rect x=\"340\" y=\"70\" width=\"40\" height=\"40\" rx=\"2\" class=\"n2 b2\"/><text x=\"240.0\" y=\"150.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">건물<\/text><rect x=\"110\" y=\"174\" width=\"20\" height=\"60\" rx=\"2\" class=\"n2 b3\"/><rect x=\"190\" y=\"174\" width=\"20\" height=\"60\" rx=\"2\" class=\"n2 b3\"/><rect x=\"270\" y=\"174\" width=\"20\" height=\"60\" rx=\"2\" class=\"n2 b3\"/><rect x=\"350\" y=\"174\" width=\"20\" height=\"60\" rx=\"2\" class=\"n2 b3\"/><line x1=\"60.0\" y1=\"234.0\" x2=\"420.0\" y2=\"234.0\" class=\"e b1\"/><text x=\"240.0\" y=\"206.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">비운 1층<\/text><text x=\"240.0\" y=\"258.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">바이센호프에서 르 코르뷔지에가 보여 줬어요<\/text><\/svg>","caption":"기둥으로 들어 올리면 1층이 비고 땅이 이어져요.","builds":4},{"kind":"points","head":"콘크리트의 또 다른 얼굴, **조소성**","items":["굳기 전 찰흙처럼 모양을 빚을 수 있는 성질이 **조소성**이에요.","막스 베르크의 센테니얼 홀은 노출된 콘크리트 구조체가 조각품처럼 일체적이에요.","멘델존의 아인슈타인 타워는 벽돌에 콘크리트를 덧씌워 **조소성**을 이용했어요.","**조소성** 덕분에 표현주의는 곡면으로 감정을 드러낼 수 있었어요."]},{"kind":"compare","head":"콘크리트가 만든 몸짓","cols":["무엇","어떤 건물"],"rows":[["**캔틸레버(cantilever)**","페레의 프랭클린가 아파트, 파리, 1903"],["**필로티(Pilotis)**","바이센호프 주거단지, 슈투트가르트, 1927"],["**평지붕(Flat Roof)**","바이센호프 주거단지와 마이스터 주택"],["**조소성**","아인슈타인 타워, 포츠담, 1921"]]},{"kind":"english","head":"논술 답안에 쓸 문장","en":"철근콘크리트는 압축에 강한 콘크리트에 인장을 버티는 철근을 넣어, 캔틸레버와 필로티를 가능하게 하였다.","ko":"재료에서 몸짓이 나온다는 순서예요.","tip":"재료, 힘, 몸짓 순서로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["바이센호프에서 조립화는 그로피우스, **필로티(Pilotis)**는 르 코르뷔지에예요.","센테니얼 홀은 노출 구조체, 아인슈타인 타워는 **조소성**이에요. 바꿔 묻는 문제가 나와요.","**평지붕(Flat Roof)**은 지붕이 아예 없다는 뜻이 아니라 평평하다는 뜻이에요."]},{"kind":"check","q":"**캔틸레버(cantilever)**가 뜻하는 것으로 알맞은 것은?","choices":["한쪽 끝만 고정하고 다른 끝은 받침 없이 내민 구조","건물을 기둥으로 들어 올려 1층을 비우는 방식","아치를 한 방향으로 밀고 나간 천장","뼈대에 커튼처럼 걸어 놓은 바깥벽"],"a":0,"why":"1층을 비우는 것은 **필로티(Pilotis)**, 밀고 나간 천장은 볼트, 걸어 놓은 벽은 커튼월이에요."},{"kind":"check","q":"콘크리트에 철근을 넣는 까닭으로 알맞은 것은?","choices":["콘크리트가 약한 **인장(Tension)**을 철근이 버텨 주기 때문","콘크리트가 약한 압축을 철근이 버텨 주기 때문","철근이 콘크리트를 더 빨리 굳게 하기 때문","철근이 겉면을 장식해 주기 때문"],"a":0,"why":"**철근콘크리트(Reinforced Concrete)**는 압축은 콘크리트가, **인장(Tension)**은 철근이 나눠 맡아요."},{"kind":"points","head":"이게 이 과목 어디에 나오나","items":["U1 p.4: 철물과 **철근콘크리트(Reinforced Concrete)**가 19세기의 두 근대적 신재료.","U4 p.4: 페레의 프랭클린가 아파트, **캔틸레버(cantilever)** 적용과 저층부 개방.","U5 p.5: 바이센호프의 **필로티(Pilotis)**와 개방적 평면, **평지붕(Flat Roof)**, 장식 없는 마감.","U6 p.5, p.7: 센테니얼 홀의 노출 콘크리트, 아인슈타인 타워의 **조소성**.","시험 모양: 건물과 개념을 짝짓는 객관식, 논술의 사례 나열에서 자주 쓰여요."]},{"kind":"recap","items":["**철근콘크리트(Reinforced Concrete)**는 압축의 콘크리트에 **인장(Tension)**의 철근을 넣은 재료예요.","**캔틸레버(cantilever)**는 한쪽만 붙잡고 내민 구조예요.","**필로티(Pilotis)**는 기둥으로 들어 올려 1층을 비워요. 지붕은 **평지붕(Flat Roof)**이에요.","**조소성**은 굳기 전 빚을 수 있는 성질이고 표현주의가 즐겨 썼어요.","기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","오늘의 용어: 철근콘크리트(Reinforced Concrete), 캔틸레버(cantilever), 필로티(Pilotis), 평지붕(Flat Roof), 조소성, 인장(Tension)"]}]},{"id":"wb-7","title":"양식과 연도 읽는 법","goal":"**양식(Style)**이 무엇인지 말하고 사진 속 건물의 시기를 좁힐 수 있어요.","terms":[{"ko":"양식","en":"Style","say":"한 시기의 건물들이 함께 지키는 형태의 규칙과 그 이름","more":"시험은 사진을 주고 양식 이름을 묻고, 논술은 그 양식을 아는 대로 모두 쓰라고 해요."},{"ko":"절충주의","en":"","say":"용도와 상관없이 여러 역사 양식을 골라 외관을 꾸민 경향","more":"부정적으로 평가하는 쪽에서는 역사주의(Historism)라고도 함. 19세기 후반의 양식적 혼란기."},{"ko":"역사주의","en":"Historism","say":"과거 고전 형상에서 영감을 얻어 양식을 되풀이하는 태도","more":"바그너는 합리적 도시 문명을 위해 역사주의를 격퇴해야 한다고 주장. 강의자료 표기는 Historism. 통상 영어 표기는 Historicism."},{"ko":"미술공예운동","en":"Arts and Crafts Movement","say":"기계 생산에 반발해 수공예의 즐거움과 정직함을 되찾자는 운동","more":"1860-1900. 1888년 런던 전시회에서 Arts and Crafts Exhibition Society 이름 처음 사용. 비싸서 대중 수요를 못 채운 한계, 아르누보에 영향."},{"ko":"아르 누보","en":"Art Nouveau","say":"과거 양식 대신 자연의 곡선으로 새 양식을 만든 예술 사조","more":"프랑스어로 새로운 미술. 1890-1910, 최고조 1890-1905. '예술에는 일정한 형식이 없다'. 비대칭, 철과 유리, 공간보다 표면과 장식."},{"ko":"매스","en":"Mass","say":"건물이 이루는 큰 덩어리","more":"모나드녹 빌딩은 매스와 비례로 현대 문명의 힘을 전해야 한다고 했고, 그로피우스는 형태와 매스에 집중했어요."}],"slides":[{"kind":"title","big":"양식과 연도","sub":"이름을 외우기 전에 이름 붙이는 규칙부터 알아요"},{"kind":"goal","items":["**양식(Style)**이 무엇인지 한 줄로 말해요.","장식으로 **양식(Style)**의 자리를 좁히는 순서를 그려요.","연도가 왜 범위로 적히는지 설명해요."]},{"kind":"points","head":"앞 단원에서 이어 붙이기","items":["기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","앞에서 **파사드(Facade)**를 읽고 구조와 재료를 봤죠.","**철근콘크리트(Reinforced Concrete)**와 판유리가 오면서 몸짓도 달라졌고요.","이제 그 모든 차이에 이름을 붙이는 방법을 배워요."]},{"kind":"points","head":"**양식(Style)**이 무엇인가요","items":["한 시기의 건물들이 함께 지키는 형태의 규칙과 그 이름이 **양식(Style)**이에요.","강의는 삶의 필요로 기술이 동원되고 그 결과가 미를 강조할 때 **양식(Style)**이 가치를 갖는다고 해요.","덩어리가 이루는 큰 부피를 **매스(Mass)**라고 하고, 크기 관계를 **비례(Proportion)**라고 해요.","모나드녹 빌딩은 **매스(Mass)**와 **비례(Proportion)**로 현대 문명의 힘을 전해야 한다고 했어요."]},{"kind":"analogy","head":"교복 보고 학교 알아맞히기","scene":"옷깃 모양과 단추 수만 봐도 어느 학교인지 알 수 있죠. 규칙이 정해져 있으니까요.","map":[["교복의 규칙","**양식(Style)**"],["옷깃과 단추","장식과 **매스(Mass)**와 재료"],["학교 이름","아르누보, 분리파 같은 이름"]]},{"kind":"figure","head":"**양식(Style)**을 좁히는 순서","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">사진에서 양식을 좁히는 순서<\/text><rect x=\"150\" y=\"36\" width=\"180\" height=\"32\" rx=\"2\" class=\"box2 b1\"/><text x=\"240.0\" y=\"58.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">장식이 있나요<\/text><line x1=\"200.0\" y1=\"70.0\" x2=\"138.5\" y2=\"91.1\" class=\"e2 b2\"/><polygon points=\"130.0,94.0 137.1,86.8 140.0,95.3\" class=\"arrow b2\"/><line x1=\"280.0\" y1=\"70.0\" x2=\"341.5\" y2=\"91.1\" class=\"e2 b2\"/><polygon points=\"350.0,94.0 340.0,95.3 342.9,86.8\" class=\"arrow b2\"/><rect x=\"20\" y=\"98\" width=\"200\" height=\"34\" rx=\"2\" class=\"n2 b2\"/><text x=\"120.0\" y=\"121.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">없다<\/text><rect x=\"260\" y=\"98\" width=\"200\" height=\"34\" rx=\"2\" class=\"n3 b2\"/><text x=\"360.0\" y=\"121.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">있다<\/text><line x1=\"120.0\" y1=\"134.0\" x2=\"120.0\" y2=\"151.0\" class=\"e2 b3\"/><polygon points=\"120.0,160.0 115.5,151.0 124.5,151.0\" class=\"arrow b3\"/><line x1=\"360.0\" y1=\"134.0\" x2=\"360.0\" y2=\"151.0\" class=\"e2 b3\"/><polygon points=\"360.0,160.0 355.5,151.0 364.5,151.0\" class=\"arrow b3\"/><rect x=\"20\" y=\"162\" width=\"200\" height=\"58\" rx=\"2\" class=\"n b3\"/><text x=\"120.0\" y=\"186.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">바그너, 로스<\/text><text x=\"120.0\" y=\"206.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">시카고 학파, 바우하우스<\/text><rect x=\"260\" y=\"162\" width=\"200\" height=\"58\" rx=\"2\" class=\"n b3\"/><text x=\"360.0\" y=\"186.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">곡선이면 아르 누보<\/text><text x=\"360.0\" y=\"206.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">기하면 분리파, 아르데코<\/text><text x=\"240.0\" y=\"250.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">주문 순서와 같아요. 싫어 -&gt; 새 장식 -&gt; 정리 -&gt; 없애<\/text><\/svg>","caption":"장식이 있나 없나부터 물어요. 그다음 곡선인가 기하인가를 봐요.","builds":4},{"kind":"points","head":"**절충주의**와 **역사주의(Historism)**","items":["과거를 모방하면서 건물의 목적과 상관없이 잡다한 **양식(Style)**으로 외관을 치장한 유행이 있었어요.","외벽은 역사적 **양식(Style)**의 견본에서 임의로 골라 장식했어요.","부정적으로 보는 입장에서 이를 **절충주의** 및 **역사주의(Historism)**라고 불러요.","**절충주의** 주택은 급경사 지붕, 박공과 지붕창, 넓은 창문에 **비례(Proportion)**체계 무시가 특징이에요."]},{"kind":"points","head":"장식으로 좁히는 순서","items":["1단계, 장식이 있나 없나 봐요. 없으면 바그너, 로스, 시카고 학파, 바우하우스 쪽이에요.","2단계, 장식이 자연에서 딴 곡선이면 **아르 누보(Art Nouveau)**와 유겐트슈틸이에요.","3단계, 장식이 자로 그은 기하면 빈 분리파와 아르데코예요.","4단계, 손맛 나는 재료와 수공예가 보이면 **미술공예운동(Arts and Crafts Movement)** 쪽이에요."]},{"kind":"figure","head":"**양식(Style)**의 연도는 범위예요","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">연도는 점이 아니라 범위예요<\/text><rect x=\"60\" y=\"60\" width=\"180\" height=\"20\" rx=\"2\" class=\"n3 b2\"/><text x=\"150.0\" y=\"74.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b2\">미술공예운동 양식<\/text><rect x=\"195\" y=\"100\" width=\"90\" height=\"20\" rx=\"2\" class=\"n b3\"/><text x=\"240.0\" y=\"114.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tl b3\">아르 누보<\/text><rect x=\"325\" y=\"140\" width=\"64\" height=\"20\" rx=\"2\" class=\"n2 b4\"/><text x=\"357.0\" y=\"154.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b4\">바우하우스<\/text><text x=\"240.0\" y=\"190.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">겹치는 구간이 있어요. 순서로 외워요<\/text><line x1=\"40.0\" y1=\"220.0\" x2=\"450.0\" y2=\"220.0\" class=\"e b1\"/><text x=\"60.0\" y=\"244.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">1860<\/text><text x=\"180.0\" y=\"244.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">1900<\/text><text x=\"300.0\" y=\"244.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">1920<\/text><text x=\"420.0\" y=\"244.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">1940<\/text><\/svg>","caption":"**미술공예운동(Arts and Crafts Movement)** 양식 1860-1900, **아르 누보(Art Nouveau)** 1890-1910, 바우하우스 1919-1933.","builds":4},{"kind":"points","head":"연도는 왜 범위인가요","items":["**양식(Style)**은 한 해에 시작해 한 해에 끝나지 않고 서서히 번져요.","**미술공예운동(Arts and Crafts Movement)**은 1860-1925, 그 **양식(Style)**은 1860-1900으로 적혀요.","**아르 누보(Art Nouveau)**는 1890-1910이고 최고조는 1890-1905예요.","바우하우스는 1919-1933, 사그라다 파밀리아는 1882부터 지금까지예요."]},{"kind":"figure","head":"한 건물의 네 가지 연도","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">한 건물에 연도가 여럿이에요<\/text><rect x=\"12\" y=\"60\" width=\"110\" height=\"60\" rx=\"2\" class=\"n b1\"/><text x=\"67.0\" y=\"86.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">설계<\/text><text x=\"67.0\" y=\"106.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b1\">1859-60<\/text><rect x=\"132\" y=\"60\" width=\"110\" height=\"60\" rx=\"2\" class=\"n2 b2\"/><text x=\"187.0\" y=\"86.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">완성<\/text><text x=\"187.0\" y=\"106.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b2\">캡션의 연도<\/text><rect x=\"252\" y=\"60\" width=\"110\" height=\"60\" rx=\"2\" class=\"n3 b3\"/><text x=\"307.0\" y=\"86.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b3\">촬영<\/text><text x=\"307.0\" y=\"106.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">1996 촬영<\/text><rect x=\"372\" y=\"60\" width=\"96\" height=\"60\" rx=\"2\" class=\"n3 b4\"/><text x=\"420.0\" y=\"86.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b4\">개보수<\/text><text x=\"420.0\" y=\"106.0\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b4\">2002년<\/text><rect x=\"40\" y=\"150\" width=\"400\" height=\"70\" rx=\"2\" class=\"box2 b4\"/><text x=\"240.0\" y=\"180.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b4\">괄호 안의 촬영, 복원, 개보수는<\/text><text x=\"240.0\" y=\"202.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b4\">건물이 완성된 해가 아니에요<\/text><text x=\"240.0\" y=\"250.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">붉은 집은 1859-60 디자인인데 캡션은 1865<\/text><\/svg>","caption":"괄호와 c. 표시를 잘 봐야 연도를 틀리지 않아요.","builds":4},{"kind":"compare","head":"연도 범위 세 개","cols":["이름","범위"],"rows":[["**미술공예운동(Arts and Crafts Movement)** 양식","1860-1900"],["**아르 누보(Art Nouveau)**","1890-1910, 최고조 1890-1905"],["바우하우스","1919-1933"],["아르데코","1925년 파리 박람회 이름에서 유래"]]},{"kind":"english","head":"논술 답안에 쓸 문장","en":"양식은 한 시기의 건물들이 공유하는 형태의 규칙이며, 장식의 유무와 성격이 그 시기를 가른다.","ko":"양식의 정의와 판단 기준을 한 문장에 담았어요.","tip":"규칙, 장식, 시기 순서로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**절충주의**와 **역사주의(Historism)**는 거의 붙어 다니지만 강의는 둘을 함께 적어요.","**미술공예운동(Arts and Crafts Movement)**는 1860-1925, 그 양식은 1860-1900이에요. 두 범위가 달라요.","아르데코의 1925는 박람회 연도예요. 양식이 그해에 시작됐다는 뜻이 아니에요."]},{"kind":"check","q":"**양식(Style)**가 뜻하는 것으로 알맞은 것은?","choices":["한 시기의 건물들이 함께 지키는 형태의 규칙과 그 이름","건물을 가로로 잘라 내려다본 그림","벽에 뚫은 창과 문 자리","건물이 둘러싼 가운데 마당"],"a":0,"why":"그림은 평면, 창은 개구부, 마당은 중정이에요."},{"kind":"check","q":"장식이 자연에서 딴 곡선일 때 가장 먼저 떠올릴 것은?","choices":["**아르 누보(Art Nouveau)**와 유겐트슈틸","빈 분리파와 아르데코","시카고 학파와 바우하우스","고딕 리바이벌과 빅토리안 고딕"],"a":0,"why":"자로 그은 기하면 분리파와 아르데코, 장식이 없으면 바그너와 로스 쪽이에요."},{"kind":"points","head":"이게 이 과목 어디에 나오나","items":["U1 p.20, p.22: 고딕 리바이벌과 **미술공예운동(Arts and Crafts Movement)** 양식 1860-1900.","U2 p.2-3: **절충주의** 및 **역사주의(Historism)**, 박공과 지붕창, **비례(Proportion)**체계 무시.","U2 p.5, p.48: **아르 누보(Art Nouveau)** 1890-1910, 아르데코의 1925년 박람회.","U3 p.2, p.13: 빈의 임페리얼 스타일과 바그너의 **역사주의(Historism)** 반대.","시험 모양: 사진을 주고 **양식(Style)** 이름을 묻거나 연도를 짝짓는 문제가 가장 많아요."]},{"kind":"recap","items":["**양식(Style)**은 한 시기 건물들이 함께 지키는 형태의 규칙이에요.","**절충주의**와 **역사주의(Historism)**는 과거 양식을 임의로 골라 치장한 경향이에요.","장식이 없나, 곡선인가, 기하인가로 좁혀요.","연도는 범위예요. **미술공예운동(Arts and Crafts Movement)** 1860-1900, **아르 누보(Art Nouveau)** 1890-1910.","기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","오늘의 용어: 양식(Style), 절충주의, 역사주의(Historism), 미술공예운동(Arts and Crafts Movement), 아르 누보(Art Nouveau), 매스(Mass)"]}]},{"id":"wb-8","title":"사진과 캡션에서 답 찾기","goal":"**캡션(Caption)**을 넉 줄로 읽고, 얇을 때는 사진에서 보이는 것만 뽑아 적을 수 있어요.","terms":[{"ko":"캡션","en":"Caption","say":"그림 밑에 붙는 건축가, 작품 이름, 도시, 연도 넉 줄","more":"이 과목의 시험은 이 넉 줄의 짝을 계속 물어요. 괄호 안의 촬영이나 복원 연도는 완성 연도가 아니에요."},{"ko":"파사드","en":"Facade","say":"건물에서 길을 향한 주된 겉면, 곧 건물의 얼굴","more":"양식의 특징이 가장 많이 드러나는 면이에요. 이 과목의 사진 문제는 거의 파사드를 보여 줘요."},{"ko":"양식","en":"Style","say":"한 시기의 건물들이 함께 지키는 형태의 규칙과 그 이름","more":"시험은 사진을 주고 양식 이름을 묻고, 논술은 그 양식을 아는 대로 모두 쓰라고 해요."},{"ko":"처마","en":"Eaves","say":"지붕이 벽 밖으로 내밀어 나온 부분","more":"처마가 깊으면 전통적인 집, 처마가 없으면 근대적인 집으로 읽히는 경우가 많아요."},{"ko":"박공","en":"Gable","say":"경사지붕의 끝에 생기는 삼각형 벽면","more":"절충주의 주택이 상투적인 수법으로 박공과 지붕창을 썼다고 강의가 지적해요."},{"ko":"지붕창","en":"Dormer","say":"경사지붕을 뚫고 올라온 작은 창","more":"박공과 함께 절충주의 주택의 상투적인 수법으로 꼽혀요."}],"slides":[{"kind":"title","big":"캡션 읽기","sub":"지어내지 않고 보이는 것만 적는 연습이에요"},{"kind":"goal","items":["**캡션(Caption)**의 넉 줄을 말하고 짝지어 외워요.","괄호와 c. 표시를 바르게 읽어요.","**캡션(Caption)**이 얇을 때 사진에서 무엇을 뽑을지 대요."]},{"kind":"points","head":"앞 단원에서 이어 붙이기","items":["기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","앞에서 **파사드(Facade)**를 네 걸음으로 읽고 **개구부(Opening)**의 크기와 배열을 봤죠.","방의 배치는 **평면(Plan)**을 봐야 알 수 있다고도 했어요.","이제 그 읽기를 시험지 위에서 쓰는 법을 배워요."]},{"kind":"points","head":"**캡션(Caption)**의 넉 줄","items":["**캡션(Caption)**은 건축가, 작품 이름, 도시와 나라, 연도의 넉 줄이에요.","예를 들어 헤리트 리트펠트, 슈뢰더 하우스, 네덜란드 위트레흐트, 1924예요.","카를 엔, 칼 마르크스 호프 주거단지, 오스트리아 빈, 1930도 같은 모양이에요.","한스 샤로운, 베를린 필하모니 홀, 독일 베를린, 1963도 그래요."]},{"kind":"figure","head":"**캡션(Caption)**의 넉 줄","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">캡션은 넉 줄로 읽어요<\/text><rect x=\"24\" y=\"48\" width=\"150\" height=\"44\" rx=\"2\" class=\"n b1\"/><text x=\"99.0\" y=\"76.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b1\">건축가<\/text><rect x=\"184\" y=\"48\" width=\"272\" height=\"44\" rx=\"2\" class=\"box b1\"/><text x=\"320.0\" y=\"76.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b1\">헤리트 리트펠트<\/text><rect x=\"24\" y=\"100\" width=\"150\" height=\"44\" rx=\"2\" class=\"n b2\"/><text x=\"99.0\" y=\"128.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b2\">작품 이름<\/text><rect x=\"184\" y=\"100\" width=\"272\" height=\"44\" rx=\"2\" class=\"box b2\"/><text x=\"320.0\" y=\"128.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b2\">슈뢰더 하우스<\/text><rect x=\"24\" y=\"152\" width=\"150\" height=\"44\" rx=\"2\" class=\"n b3\"/><text x=\"99.0\" y=\"180.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b3\">도시와 나라<\/text><rect x=\"184\" y=\"152\" width=\"272\" height=\"44\" rx=\"2\" class=\"box b3\"/><text x=\"320.0\" y=\"180.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b3\">네덜란드 위트레흐트<\/text><rect x=\"24\" y=\"204\" width=\"150\" height=\"44\" rx=\"2\" class=\"n b4\"/><text x=\"99.0\" y=\"232.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b4\">연도<\/text><rect x=\"184\" y=\"204\" width=\"272\" height=\"44\" rx=\"2\" class=\"box b4\"/><text x=\"320.0\" y=\"232.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tl b4\">1924<\/text><\/svg>","caption":"이 네 짝을 함께 외워야 객관식과 단답에서 흔들리지 않아요.","builds":4},{"kind":"analogy","head":"사진 뒤에 적힌 메모","scene":"옛날 사진 뒤에는 누가, 무엇을, 어디서, 언제 찍었는지 연필로 적혀 있죠.","map":[["누가","건축가"],["무엇을","작품 이름"],["어디서","도시와 나라"],["언제","연도"]]},{"kind":"points","head":"괄호와 c. 읽기","items":["연도 뒤 괄호에 촬영, 복원, 개보수, 철거가 붙으면 완성 연도가 아니에요.","로스하우스는 1912이고 괄호의 1996은 사진을 찍은 해예요.","칠레하우스는 1924이고 2002년은 개보수 연도예요.","c. 가 붙으면 대략이라는 뜻이라 연도를 범위로 기억하는 편이 안전해요."]},{"kind":"points","head":"지붕에서 읽는 것","items":["지붕이 벽 밖으로 내민 부분이 **처마(Eaves)**예요.","경사지붕 끝에 생기는 삼각형 벽면이 **박공(Gable)**이고, 지붕을 뚫고 올라온 창이 **지붕창(Dormer)**이에요.","절충주의 주택은 급경사 지붕에 **박공(Gable)**과 **지붕창(Dormer)**을 상투적으로 썼어요.","매킨토시의 힐하우스는 얕은 **처마(Eaves)**와 급경사 슬레이트 지붕이에요."]},{"kind":"figure","head":"사진에서 뽑을 여섯 가지","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">캡션이 얇으면 사진에서 뽑아요<\/text><rect x=\"16\" y=\"48\" width=\"220\" height=\"44\" rx=\"2\" class=\"n b1\"/><text x=\"126.0\" y=\"66.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">재료<\/text><text x=\"126.0\" y=\"86.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">돌 벽돌 회반죽 철 유리<\/text><rect x=\"244\" y=\"48\" width=\"220\" height=\"44\" rx=\"2\" class=\"n b1\"/><text x=\"354.0\" y=\"66.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">개구부<\/text><text x=\"354.0\" y=\"86.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">크기 모양 배열<\/text><rect x=\"16\" y=\"100\" width=\"220\" height=\"44\" rx=\"2\" class=\"n b2\"/><text x=\"126.0\" y=\"118.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">지붕<\/text><text x=\"126.0\" y=\"138.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">평지붕인가 박공인가<\/text><rect x=\"244\" y=\"100\" width=\"220\" height=\"44\" rx=\"2\" class=\"n b2\"/><text x=\"354.0\" y=\"118.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">처마<\/text><text x=\"354.0\" y=\"138.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">깊은가 없는가<\/text><rect x=\"16\" y=\"152\" width=\"220\" height=\"44\" rx=\"2\" class=\"n3 b3\"/><text x=\"126.0\" y=\"170.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b3\">장식<\/text><text x=\"126.0\" y=\"190.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">곡선 기하 없음<\/text><rect x=\"244\" y=\"152\" width=\"220\" height=\"44\" rx=\"2\" class=\"n3 b3\"/><text x=\"354.0\" y=\"170.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b3\">덩어리<\/text><text x=\"354.0\" y=\"190.0\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">몇 개로 나뉘나<\/text><rect x=\"60\" y=\"208\" width=\"360\" height=\"48\" rx=\"2\" class=\"box2 b4\"/><text x=\"240.0\" y=\"238.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b4\">이름과 연도는 확실할 때만 적어요<\/text><\/svg>","caption":"**처마(Eaves)**가 없는 **박공(Gable)**과 **지붕창(Dormer)**이 있는 지붕은 서로 다른 시기를 가리켜요.","builds":4},{"kind":"points","head":"**캡션(Caption)**이 얇을 때","items":["보이는 것만 적어요. 재료, 개구부, 지붕과 **처마(Eaves)**, 장식, 덩어리 구성이에요.","그다음 **파사드(Facade)**의 장식으로 **양식(Style)**의 자리를 좁혀요.","사진만으로 알 수 없는 이름과 연도는 지어내지 않아요.","마이스터 주택처럼 **처마(Eaves)**도 인방도 없는 매끈한 얼굴이면 근대 쪽이에요."]},{"kind":"figure","head":"답안 다섯 단계","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240.0\" y=\"22.0\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">사진 문제 답안 다섯 단계<\/text><rect x=\"40\" y=\"44\" width=\"400\" height=\"36\" rx=\"2\" class=\"box b1\"/><text x=\"240.0\" y=\"68.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b1\">1 캡션에 있는 넉 줄을 그대로 옮겨요<\/text><rect x=\"40\" y=\"88\" width=\"400\" height=\"36\" rx=\"2\" class=\"box b2\"/><text x=\"240.0\" y=\"112.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b2\">2 보이는 것을 적어요. 재료, 개구부, 지붕<\/text><rect x=\"40\" y=\"132\" width=\"400\" height=\"36\" rx=\"2\" class=\"box b3\"/><text x=\"240.0\" y=\"156.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b3\">3 장식으로 양식의 자리를 잡아요<\/text><rect x=\"40\" y=\"176\" width=\"400\" height=\"36\" rx=\"2\" class=\"box b4\"/><text x=\"240.0\" y=\"200.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b4\">4 대비되는 건물을 하나 붙여요<\/text><rect x=\"40\" y=\"220\" width=\"400\" height=\"36\" rx=\"2\" class=\"box2 b4\"/><text x=\"240.0\" y=\"244.0\" font-size=\"16\" text-anchor=\"middle\" class=\"tl b4\">5 확실하지 않은 것은 쓰지 않아요<\/text><\/svg>","caption":"이 과목 논술은 아는 대로 모두 쓰는 모양이라 빠짐없이 나열하는 편이 유리해요.","builds":4},{"kind":"compare","head":"**캡션(Caption)**에서 바로 뽑는 것","cols":["칸","예"],"rows":[["건축가","프리츠 회거"],["작품 이름","칠레하우스"],["도시와 나라","독일 함부르크"],["연도","1924, 괄호의 2002는 개보수"]]},{"kind":"english","head":"논술 답안에 쓸 문장","en":"캡션은 건축가와 작품 이름과 도시와 연도로 이루어지며, 괄호 안의 연도는 완성 연도가 아니다.","ko":"캡션 읽는 규칙을 한 문장으로 정리했어요.","tip":"건축가, 작품, 도시, 연도 순서로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["붉은 집은 1859-60년 디자인인데 U1 p.23 **캡션(Caption)**에는 1865로 적혀 있어요.","U2 p.12 **캡션(Caption)**에는 c. 1990, p.13 에는 c.1900 이라 표기가 엇갈려요.","**박공(Gable)**과 **지붕창(Dormer)**은 둘 다 경사지붕에 딸린 말이라 바꿔 묻기 좋아요."]},{"kind":"check","q":"**캡션(Caption)**이 보통 적는 네 가지는?","choices":["건축가, 작품 이름, 도시와 나라, 연도","재료, 층수, 면적, 공사비","양식, 구조, 설비, 준공일","건축가, 발주처, 도면, 사진가"],"a":0,"why":"이 네 짝을 함께 외워야 객관식과 단답에서 흔들리지 않아요."},{"kind":"check","q":"경사지붕 끝에 생기는 삼각형 벽면을 부르는 말은?","choices":["**박공(Gable)**","**지붕창(Dormer)**","**처마(Eaves)**","**파사드(Facade)**"],"a":0,"why":"지붕을 뚫고 올라온 창은 **지붕창(Dormer)**, 지붕이 내민 부분은 **처마(Eaves)**예요."},{"kind":"points","head":"이게 이 과목 어디에 나오나","items":["U1 p.22-23: 붉은 집의 1859-60 디자인과 1865 **캡션(Caption)**.","U2 p.3, p.12-13: **박공(Gable)**과 **지붕창(Dormer)**을 쓴 절충주의 주택, c. 표기.","U3 p.42: 로스하우스 1912 뒤에 붙은 1996 촬영 표시.","U4 p.33, U5 p.3, U6 p.17: 슈뢰더 하우스, 칼 마르크스 호프, 필하모니 홀 **캡션(Caption)**.","시험 모양: 사진과 **양식(Style)**을 짝짓는 객관식, 건축가나 도시를 쓰는 단답이 나와요."]},{"kind":"recap","items":["**캡션(Caption)**은 건축가, 작품 이름, 도시와 나라, 연도의 넉 줄이에요.","괄호의 촬영, 복원, 개보수는 완성 연도가 아니고 c. 는 대략이에요.","지붕에서는 **처마(Eaves)**, **박공(Gable)**, **지붕창(Dormer)**을 봐요.","얇으면 보이는 것만 적고 **양식(Style)**은 장식으로 좁혀요.","기계 시대에 건축은 어떻게 생겨야 하나? 싫어 -> 새 장식 -> 정리 -> 없애.","오늘의 용어: 캡션(Caption), 파사드(Facade), 양식(Style), 처마(Eaves), 박공(Gable), 지붕창(Dormer)"]}]}]};
